-- VERTU: complete database setup for a NEW, empty Supabase project.
-- Paste all of it into Supabase -> SQL Editor -> New query, and press Run. Run it only once.
-- Generated by scripts/make-setup-sql.mjs; do not edit by hand.

-- ===== 20261112000000_phase1_core.sql
-- VERTU Phase 1: catalogue, editorial content, orders, staff roles, audit trail.
-- Run once on a new Supabase project (SQL editor, or `supabase db push`).
-- Prices are whole rupees (integer). Razorpay works in paise: multiply by 100 at checkout.

-- ---------------------------------------------------------------- tables

create table public.categories (
  id    text primary key,
  name  text not null,
  code  text not null unique,
  unit  text not null,
  sort  int  not null default 0
);

create table public.products (
  id          text primary key check (id ~ '^[A-Z0-9-]{3,40}$'),
  category    text not null references public.categories (id),
  colour      text not null check (char_length(colour) between 1 and 40),
  hex         text not null default '#22201d' check (hex ~ '^#[0-9a-fA-F]{6}$'),
  price       int  not null check (price >= 0 and price <= 10000000),
  stock       int  not null default 0 check (stock >= 0),
  status      text not null default 'draft' check (status in ('active', 'draft')),
  image       text not null default '',
  description text not null default '' check (char_length(description) <= 2000),
  sort        int  not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index products_category_idx on public.products (category, sort);

-- Exactly one row. `published` is the editorial JSON the storefront renders.
create table public.site_content (
  id           int primary key default 1 check (id = 1),
  published    jsonb not null,
  published_at timestamptz,
  updated_at   timestamptz not null default now()
);

create table public.settings (
  id         int primary key default 1 check (id = 1),
  low_stock  int not null default 5 check (low_stock between 0 and 999),
  updated_at timestamptz not null default now()
);

create sequence public.order_number_seq start 10500;

create table public.orders (
  id             text primary key default ('VRT-' || nextval('public.order_number_seq')),
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  status         text not null default 'Pending'
                 check (status in ('Pending', 'Processing', 'Shipped', 'Delivered')),
  customer_id    uuid references auth.users (id) on delete set null,
  customer_name  text not null,
  customer_email text not null,
  customer_phone text not null default '',
  ship_address   text not null default '',
  ship_city      text not null default '',
  ship_state     text not null default '',
  ship_pin       text not null default '',
  note           text not null default ''
);
create index orders_created_idx on public.orders (created_at desc);
create index orders_status_idx on public.orders (status);

create table public.order_items (
  id       bigint generated always as identity primary key,
  order_id text not null references public.orders (id) on delete cascade,
  sku      text not null,
  category text not null,
  colour   text not null,
  price    int  not null check (price >= 0),
  qty      int  not null check (qty > 0)
);
create index order_items_order_idx on public.order_items (order_id);

create table public.admin_users (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  role       text not null check (role in ('owner', 'staff')),
  created_at timestamptz not null default now(),
  added_by   uuid
);

create table public.inventory_log (
  id          bigint generated always as identity primary key,
  created_at  timestamptz not null default now(),
  sku         text not null,
  delta       int  not null,
  stock_after int  not null,
  reason      text not null default 'manual',
  actor       uuid
);
create index inventory_log_sku_idx on public.inventory_log (sku, created_at desc);

create table public.audit_log (
  id         bigint generated always as identity primary key,
  created_at timestamptz not null default now(),
  actor      uuid,
  action     text not null,
  entity     text not null,
  entity_id  text,
  changes    jsonb
);
create index audit_log_created_idx on public.audit_log (created_at desc);

-- ---------------------------------------------------------------- roles
-- Admin rights require BOTH a row in admin_users AND a two-step-verified session (aal2).

create function public.admin_role() returns text
language sql stable security definer set search_path = '' as $$
  select au.role from public.admin_users au
  where au.user_id = auth.uid()
    and coalesce(auth.jwt() ->> 'aal', 'aal1') = 'aal2'
$$;

create function public.is_admin() returns boolean
language sql stable security definer set search_path = '' as $$
  select public.admin_role() is not null
$$;

create function public.is_owner() returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce(public.admin_role() = 'owner', false)
$$;

-- ---------------------------------------------------------------- triggers

create function public.touch_updated_at() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  return new;
end $$;

create trigger products_touch before update on public.products
  for each row execute function public.touch_updated_at();
create trigger orders_touch before update on public.orders
  for each row execute function public.touch_updated_at();
create trigger site_content_touch before update on public.site_content
  for each row execute function public.touch_updated_at();
create trigger settings_touch before update on public.settings
  for each row execute function public.touch_updated_at();

-- Every stock movement is recorded. Checkout (Phase 3) sets vertu.stock_reason = 'order'.
create function public.log_stock() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  before_stock int := case when tg_op = 'INSERT' then 0 else old.stock end;
begin
  if new.stock is distinct from before_stock then
    insert into public.inventory_log (sku, delta, stock_after, reason, actor)
    values (new.id, new.stock - before_stock, new.stock,
            coalesce(nullif(current_setting('vertu.stock_reason', true), ''),
                     case when tg_op = 'INSERT' then 'created' else 'manual' end),
            auth.uid());
  end if;
  return new;
end $$;

create trigger products_stock_log after insert or update of stock on public.products
  for each row execute function public.log_stock();

-- Who changed what. Long values (images, editorial JSON) are recorded as '(changed)'.
create function public.audit() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  diff jsonb := '{}'::jsonb;
  k text;
  a jsonb;
  b jsonb;
  key_col text := tg_argv[0];
  rec jsonb := to_jsonb(coalesce(new, old));
begin
  if tg_op = 'UPDATE' then
    for k in select jsonb_object_keys(to_jsonb(new)) loop
      continue when k in ('updated_at');
      a := to_jsonb(old) -> k;
      b := to_jsonb(new) -> k;
      if a is distinct from b then
        diff := diff || jsonb_build_object(k,
          case when length(coalesce(a::text, '')) > 300 or length(coalesce(b::text, '')) > 300
               then to_jsonb('(changed)'::text)
               else jsonb_build_object('from', a, 'to', b) end);
      end if;
    end loop;
    if diff = '{}'::jsonb then return new; end if;
  elsif tg_op = 'INSERT' then
    diff := jsonb_strip_nulls(to_jsonb(new) - 'published' - 'image' - 'description');
  else
    diff := jsonb_strip_nulls(to_jsonb(old) - 'published' - 'image' - 'description');
  end if;
  insert into public.audit_log (actor, action, entity, entity_id, changes)
  values (auth.uid(), lower(tg_op), tg_table_name, rec ->> key_col, diff);
  return coalesce(new, old);
end $$;

create trigger products_audit after insert or update or delete on public.products
  for each row execute function public.audit('id');
create trigger orders_audit after update on public.orders
  for each row execute function public.audit('id');
create trigger site_content_audit after update on public.site_content
  for each row execute function public.audit('id');
create trigger settings_audit after update on public.settings
  for each row execute function public.audit('id');
create trigger admin_users_audit after insert or update or delete on public.admin_users
  for each row execute function public.audit('user_id');

-- ---------------------------------------------------------------- row level security

alter table public.categories    enable row level security;
alter table public.products      enable row level security;
alter table public.site_content  enable row level security;
alter table public.settings      enable row level security;
alter table public.orders        enable row level security;
alter table public.order_items   enable row level security;
alter table public.admin_users   enable row level security;
alter table public.inventory_log enable row level security;
alter table public.audit_log     enable row level security;

-- Shoppers (anon or signed in) see live products and published editorial only.
create policy "categories readable" on public.categories for select using (true);
create policy "categories owner write" on public.categories for all
  using (public.is_owner()) with check (public.is_owner());

create policy "products readable" on public.products for select
  using (status = 'active' or public.is_admin());
create policy "products admin insert" on public.products for insert
  with check (public.is_admin());
create policy "products admin update" on public.products for update
  using (public.is_admin()) with check (public.is_admin());
create policy "products owner delete" on public.products for delete
  using (public.is_owner());

create policy "content readable" on public.site_content for select using (true);
create policy "content admin update" on public.site_content for update
  using (public.is_admin()) with check (public.is_admin());

create policy "settings admin read" on public.settings for select using (public.is_admin());
create policy "settings owner update" on public.settings for update
  using (public.is_owner()) with check (public.is_owner());

-- Orders are created by the checkout server function (Phase 3, service role), never by browsers.
create policy "orders admin read" on public.orders for select using (public.is_admin());
create policy "orders admin update" on public.orders for update
  using (public.is_admin()) with check (public.is_admin());
create policy "order items admin read" on public.order_items for select using (public.is_admin());

-- People can see their own staff row (so the admin can say "two-step verification needed").
create policy "admin_users self or admin read" on public.admin_users for select
  using (user_id = auth.uid() or public.is_admin());

create policy "inventory log admin read" on public.inventory_log for select using (public.is_admin());
create policy "audit log owner read" on public.audit_log for select using (public.is_owner());

-- Column-level limits on top of the policies.
revoke insert, update, delete on public.orders, public.order_items from anon, authenticated;
grant update (status, note) on public.orders to authenticated;
revoke insert, update, delete on public.admin_users, public.inventory_log, public.audit_log from anon, authenticated;
revoke insert, delete on public.site_content, public.settings from anon, authenticated;

-- ---------------------------------------------------------------- team management (owners)

create function public.team_list()
returns table (user_id uuid, email text, role text, created_at timestamptz, last_sign_in_at timestamptz)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.is_owner() then raise exception 'not_allowed' using errcode = '42501'; end if;
  return query
    select au.user_id, u.email::text, au.role, au.created_at, u.last_sign_in_at
    from public.admin_users au join auth.users u on u.id = au.user_id
    order by au.role, u.email;
end $$;

create function public.team_grant(p_email text, p_role text) returns void
language plpgsql security definer set search_path = '' as $$
declare
  uid uuid;
begin
  if not public.is_owner() then raise exception 'not_allowed' using errcode = '42501'; end if;
  if p_role not in ('owner', 'staff') then raise exception 'bad_role' using errcode = '22023'; end if;
  select id into uid from auth.users where lower(email) = lower(trim(p_email));
  if uid is null then raise exception 'no_account' using errcode = 'P0002'; end if;
  if uid = auth.uid() and p_role <> 'owner' then raise exception 'cannot_demote_self' using errcode = '42501'; end if;
  insert into public.admin_users (user_id, role, added_by) values (uid, p_role, auth.uid())
  on conflict (user_id) do update set role = excluded.role;
end $$;

create function public.team_revoke(p_user uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_owner() then raise exception 'not_allowed' using errcode = '42501'; end if;
  if p_user = auth.uid() then raise exception 'cannot_remove_self' using errcode = '42501'; end if;
  delete from public.admin_users where user_id = p_user;
end $$;

-- Recent activity with the person's email, for owners.
create function public.activity(p_limit int default 40)
returns table (created_at timestamptz, email text, action text, entity text, entity_id text, changes jsonb)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.is_owner() then raise exception 'not_allowed' using errcode = '42501'; end if;
  return query
    select l.created_at, u.email::text, l.action, l.entity, l.entity_id, l.changes
    from public.audit_log l left join auth.users u on u.id = l.actor
    order by l.created_at desc limit least(greatest(p_limit, 1), 200);
end $$;

revoke execute on function public.team_list(), public.team_grant(text, text),
  public.team_revoke(uuid), public.activity(int) from anon;

-- ---------------------------------------------------------------- image storage

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('media', 'media', true, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

create policy "media admin upload" on storage.objects for insert to authenticated
  with check (bucket_id = 'media' and public.is_admin());
create policy "media admin read" on storage.objects for select to authenticated
  using (bucket_id = 'media' and public.is_admin());
create policy "media admin update" on storage.objects for update to authenticated
  using (bucket_id = 'media' and public.is_admin());
create policy "media admin delete" on storage.objects for delete to authenticated
  using (bucket_id = 'media' and public.is_admin());


-- ===== 20261112010000_phase2_customers.sql
-- VERTU Phase 2: customer accounts, address book, wishlist, saved bag, back-in-stock alerts,
-- collection details for product pages, and customers reading their own orders.

-- ---------------------------------------------------------------- collection details

alter table public.categories
  add column description text  not null default '' check (char_length(description) <= 2000),
  add column details     jsonb not null default '{}'::jsonb check (jsonb_typeof(details) = 'object');
-- details shape: { "features": [text], "specs": { "Dimensions": text, "Material": text, ... }, "care": text }

create trigger categories_audit after update on public.categories
  for each row execute function public.audit('id');

-- Staff edit collection copy (like editorial); adding or removing collections stays with owners.
create policy "categories admin update" on public.categories for update
  using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------- profiles

create table public.profiles (
  id               uuid primary key references auth.users (id) on delete cascade,
  full_name        text not null default '' check (char_length(full_name) <= 120),
  phone            text not null default '' check (phone = '' or phone ~ '^\+91[6-9][0-9]{9}$'),
  marketing_opt_in boolean not null default false,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create trigger profiles_touch before update on public.profiles
  for each row execute function public.touch_updated_at();

-- Every new account gets a profile row.
create function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles (id, full_name)
  values (new.id, left(coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name', ''), 120))
  on conflict (id) do nothing;
  return new;
end $$;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------- addresses

create table public.addresses (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null default auth.uid() references auth.users (id) on delete cascade,
  label      text not null default '' check (char_length(label) <= 40),
  full_name  text not null check (char_length(full_name) between 1 and 120),
  phone      text not null check (phone ~ '^\+91[6-9][0-9]{9}$'),
  line1      text not null check (char_length(line1) between 1 and 200),
  line2      text not null default '' check (char_length(line2) <= 200),
  city       text not null check (char_length(city) between 1 and 80),
  state      text not null check (char_length(state) between 1 and 60),
  pin        text not null check (pin ~ '^[1-9][0-9]{5}$'),
  is_default boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index addresses_user_idx on public.addresses (user_id);
create trigger addresses_touch before update on public.addresses
  for each row execute function public.touch_updated_at();

-- At most 10 addresses per person; the first one is the default; choosing a new default unsets the old.
create function public.addresses_rules() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if pg_trigger_depth() > 1 then return new; end if; -- the unset-other-defaults update below
  if tg_op = 'INSERT' and (select count(*) from public.addresses where user_id = new.user_id) >= 10 then
    raise exception 'address_limit' using errcode = '23514';
  end if;
  if new.is_default then
    update public.addresses set is_default = false
    where user_id = new.user_id and id <> new.id and is_default;
  elsif tg_op = 'INSERT' and not exists (select 1 from public.addresses where user_id = new.user_id and is_default) then
    new.is_default := true;
  end if;
  return new;
end $$;
create trigger addresses_rules before insert or update of is_default on public.addresses
  for each row execute function public.addresses_rules();

-- ---------------------------------------------------------------- wishlist, saved bag

create table public.wishlist_items (
  user_id    uuid not null default auth.uid() references auth.users (id) on delete cascade,
  sku        text not null references public.products (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, sku)
);

create table public.carts (
  user_id    uuid primary key default auth.uid() references auth.users (id) on delete cascade,
  items      jsonb not null default '[]'::jsonb
             check (jsonb_typeof(items) = 'array' and jsonb_array_length(items) <= 50),
  updated_at timestamptz not null default now()
);
create trigger carts_touch before update on public.carts
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------- back-in-stock alerts
-- Anyone can ask to be told when a sold-out colour returns. Emails go out in Phase 4.

create table public.stock_alerts (
  id          bigint generated always as identity primary key,
  sku         text not null references public.products (id) on delete cascade,
  email       text not null check (char_length(email) <= 254 and email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  user_id     uuid default auth.uid() references auth.users (id) on delete set null,
  created_at  timestamptz not null default now(),
  notified_at timestamptz,
  unique (sku, email)
);
create index stock_alerts_pending_idx on public.stock_alerts (sku) where notified_at is null;

-- ---------------------------------------------------------------- privacy requests (DPDP Act)

create table public.data_requests (
  id          bigint generated always as identity primary key,
  user_id     uuid default auth.uid() references auth.users (id) on delete set null,
  email       text not null,
  kind        text not null check (kind in ('delete', 'export')),
  created_at  timestamptz not null default now(),
  resolved_at timestamptz
);

-- ---------------------------------------------------------------- row level security

alter table public.profiles       enable row level security;
alter table public.addresses      enable row level security;
alter table public.wishlist_items enable row level security;
alter table public.carts          enable row level security;
alter table public.stock_alerts   enable row level security;
alter table public.data_requests  enable row level security;

create policy "profile own read" on public.profiles for select using (id = auth.uid() or public.is_admin());
create policy "profile own update" on public.profiles for update using (id = auth.uid()) with check (id = auth.uid());

create policy "addresses own" on public.addresses for all
  using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "addresses admin read" on public.addresses for select using (public.is_admin());

create policy "wishlist own" on public.wishlist_items for all
  using (user_id = auth.uid()) with check (user_id = auth.uid());

create policy "cart own" on public.carts for all
  using (user_id = auth.uid()) with check (user_id = auth.uid());

create policy "stock alert anyone asks" on public.stock_alerts for insert
  with check (
    notified_at is null
    and (user_id is null or user_id = auth.uid())
    and exists (select 1 from public.products p where p.id = sku and p.status = 'active')
  );
create policy "stock alert own or admin read" on public.stock_alerts for select
  using (user_id = auth.uid() or public.is_admin());
create policy "stock alert own delete" on public.stock_alerts for delete using (user_id = auth.uid());

create policy "data request own insert" on public.data_requests for insert
  with check (user_id = auth.uid() and resolved_at is null);
create policy "data request own or owner read" on public.data_requests for select
  using (user_id = auth.uid() or public.is_owner());
create policy "data request owner resolve" on public.data_requests for update
  using (public.is_owner()) with check (public.is_owner());

-- Customers see their own orders. (Orders are still only created by the checkout server, Phase 3.)
create policy "orders own read" on public.orders for select using (customer_id = auth.uid());
create policy "order items own read" on public.order_items for select
  using (exists (select 1 from public.orders o where o.id = order_id and o.customer_id = auth.uid()));

-- Column limits: people cannot rename their profile id or move rows between accounts.
revoke insert, delete on public.profiles from anon, authenticated;
revoke update on public.profiles from anon, authenticated;
grant update (full_name, phone, marketing_opt_in) on public.profiles to authenticated;
revoke update on public.stock_alerts from anon, authenticated;
revoke insert, update, delete on public.addresses, public.wishlist_items, public.carts, public.data_requests from anon;


-- ===== 20261112020000_phase3_checkout.sql
-- VERTU Phase 3: checkout, payments (Razorpay + cash on delivery), coupons, stock holds, refunds.
--
-- Money rule: the browser never decides a price. Every total is recomputed here from the live
-- products table. Orders are only created by create_order(), which only the server (service role) may call.
-- Amounts are whole rupees; Razorpay receives total * 100 (paise).

-- ---------------------------------------------------------------- store settings

alter table public.settings
  add column shipping_fee       int  not null default 0     check (shipping_fee between 0 and 100000),
  add column free_shipping_over int  not null default 0     check (free_shipping_over >= 0), -- 0 = no threshold
  add column cod_enabled        bool not null default false,
  add column cod_fee            int  not null default 0     check (cod_fee between 0 and 100000),
  add column cod_max            int  not null default 5000  check (cod_max >= 0),
  add column hold_minutes       int  not null default 15    check (hold_minutes between 5 and 120);

-- Shoppers need the shipping rules to show them (nothing secret in here).
create or replace function public.store_rules() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('shipping_fee', shipping_fee, 'free_shipping_over', free_shipping_over,
    'cod_enabled', cod_enabled, 'cod_fee', cod_fee, 'cod_max', cod_max)
  from public.settings where id = 1
$$;

-- ---------------------------------------------------------------- orders: totals and payment

alter table public.orders drop constraint orders_status_check;
alter table public.orders add constraint orders_status_check
  check (status in ('Pending', 'Processing', 'Shipped', 'Delivered', 'Cancelled'));

alter table public.orders
  add column subtotal            int  check (subtotal >= 0),
  add column discount            int  not null default 0 check (discount >= 0),
  add column shipping            int  not null default 0 check (shipping >= 0),
  add column cod_fee             int  not null default 0 check (cod_fee >= 0),
  add column total               int  check (total >= 0),
  add column coupon_code         text,
  add column payment_method      text not null default 'manual' check (payment_method in ('razorpay', 'cod', 'manual')),
  add column payment_status      text not null default 'paid'
             check (payment_status in ('awaiting', 'paid', 'cod', 'failed', 'expired', 'refunded', 'partially_refunded', 'cancelled')),
  add column razorpay_order_id   text unique,
  add column razorpay_payment_id text,
  add column paid_at             timestamptz,
  add column expires_at          timestamptz,
  add column refunded_amount     int  not null default 0 check (refunded_amount >= 0),
  add column access_token        uuid not null default gen_random_uuid(),
  add column flag                text; -- set when a person needs to look (e.g. paid after the hold expired and stock ran out)

-- Existing orders (entered before checkout existed) count as paid; fill their totals.
update public.orders o set
  subtotal = coalesce((select sum(price * qty) from public.order_items i where i.order_id = o.id), 0),
  total    = coalesce((select sum(price * qty) from public.order_items i where i.order_id = o.id), 0)
where subtotal is null;

create index orders_awaiting_idx on public.orders (expires_at) where payment_status = 'awaiting';
create index orders_email_idx on public.orders (lower(customer_email));

-- Cash on delivery is collected by the courier: delivered means paid.
create function public.cod_collected() returns trigger
language plpgsql set search_path = '' as $$
begin
  if new.status = 'Delivered' and new.payment_status = 'cod' then
    new.payment_status := 'paid';
    new.paid_at := now();
  end if;
  return new;
end $$;
create trigger orders_cod_collected before update of status on public.orders
  for each row execute function public.cod_collected();

-- Staff may not cancel from the status buttons: cancelling must go through cancel/refund (it restocks and refunds).
create function public.orders_status_guard() returns trigger
language plpgsql set search_path = '' as $$
begin
  if current_setting('vertu.system', true) = 'yes' then return new; end if; -- checkout/refund functions
  if new.status = 'Cancelled' and old.status <> 'Cancelled' then
    raise exception 'use_cancel' using errcode = '42501';
  end if;
  if old.status = 'Cancelled' and new.status <> 'Cancelled' then
    raise exception 'order_cancelled' using errcode = '42501';
  end if;
  if new.status <> old.status and old.payment_status in ('awaiting', 'failed', 'expired') then
    raise exception 'order_unpaid' using errcode = '42501';
  end if;
  return new;
end $$;
create trigger orders_status_guard before update of status on public.orders
  for each row execute function public.orders_status_guard();

-- ---------------------------------------------------------------- coupons

create table public.coupons (
  code         text primary key check (code ~ '^[A-Z0-9_-]{3,24}$'),
  kind         text not null check (kind in ('percent', 'amount')),
  value        int  not null check (value > 0),
  min_subtotal int  not null default 0 check (min_subtotal >= 0),
  starts_at    timestamptz,
  ends_at      timestamptz,
  max_uses     int  check (max_uses > 0),
  used_count   int  not null default 0 check (used_count >= 0),
  active       bool not null default true,
  note         text not null default '',
  created_at   timestamptz not null default now(),
  check (kind <> 'percent' or value <= 90),
  check (ends_at is null or starts_at is null or ends_at > starts_at)
);
alter table public.coupons enable row level security;
create policy "coupons admin" on public.coupons for all using (public.is_admin()) with check (public.is_admin());
create trigger coupons_audit after insert or update or delete on public.coupons
  for each row execute function public.audit('code');

-- ---------------------------------------------------------------- pricing (one function, used for quotes and orders)

-- p_items: [{ "sku": "VRT-SL-CRI", "qty": 2 }, ...]
-- Returns the authoritative quote. "problems" lists anything that stops checkout.
create function public.price_cart(p_items jsonb, p_coupon text default null, p_method text default 'razorpay')
returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  s public.settings;
  c public.coupons;
  lines jsonb := '[]'::jsonb;
  problems jsonb := '[]'::jsonb;
  item jsonb;
  p public.products;
  qty int;
  subtotal int := 0;
  discount int := 0;
  shipping int := 0;
  codfee int := 0;
  coupon jsonb := null;
  v_code text := upper(nullif(trim(coalesce(p_coupon, '')), ''));
  n int := 0;
begin
  select * into s from public.settings where id = 1;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    return jsonb_build_object('problems', jsonb_build_array(jsonb_build_object('kind', 'empty')));
  end if;
  if jsonb_array_length(p_items) > 20 then
    return jsonb_build_object('problems', jsonb_build_array(jsonb_build_object('kind', 'too_many_lines')));
  end if;
  if p_method not in ('razorpay', 'cod') then
    return jsonb_build_object('problems', jsonb_build_array(jsonb_build_object('kind', 'bad_method')));
  end if;

  for item in select value from jsonb_array_elements(p_items) loop
    n := n + 1;
    qty := case when (item ->> 'qty') ~ '^[0-9]{1,2}$' then (item ->> 'qty')::int else 0 end;
    select * into p from public.products where id = item ->> 'sku';
    if p.id is null or p.status <> 'active' then
      problems := problems || jsonb_build_object('kind', 'unavailable', 'sku', item ->> 'sku');
      continue;
    end if;
    if qty < 1 or qty > 9 then
      problems := problems || jsonb_build_object('kind', 'bad_qty', 'sku', p.id);
      continue;
    end if;
    if p.stock < qty then
      problems := problems || jsonb_build_object('kind', 'insufficient', 'sku', p.id, 'available', p.stock);
    end if;
    if lines @> jsonb_build_array(jsonb_build_object('sku', p.id)) then
      problems := problems || jsonb_build_object('kind', 'duplicate', 'sku', p.id);
      continue;
    end if;
    lines := lines || jsonb_build_object('sku', p.id, 'category', p.category, 'colour', p.colour,
                                         'price', p.price, 'qty', qty, 'image', p.image);
    subtotal := subtotal + p.price * qty;
  end loop;

  if v_code is not null then
    select * into c from public.coupons cc where cc.code = v_code;
    coupon := jsonb_build_object('code', v_code, 'valid', false);
    if c.code is null or not c.active then
      coupon := coupon || '{"reason": "not_found"}';
    elsif c.starts_at is not null and now() < c.starts_at then
      coupon := coupon || '{"reason": "not_started"}';
    elsif c.ends_at is not null and now() > c.ends_at then
      coupon := coupon || '{"reason": "expired"}';
    elsif c.max_uses is not null and c.used_count >= c.max_uses then
      coupon := coupon || '{"reason": "used_up"}';
    elsif subtotal < c.min_subtotal then
      coupon := coupon || jsonb_build_object('reason', 'min_subtotal', 'min_subtotal', c.min_subtotal);
    else
      discount := case when c.kind = 'percent' then floor(subtotal * c.value / 100.0)::int else least(c.value, subtotal) end;
      coupon := jsonb_build_object('code', v_code, 'valid', true, 'kind', c.kind, 'value', c.value);
    end if;
  end if;

  -- shipping_fee applies unless the order reaches free_shipping_over (0 = no free-shipping threshold)
  shipping := case when s.free_shipping_over > 0 and subtotal - discount >= s.free_shipping_over then 0 else s.shipping_fee end;

  if p_method = 'cod' then
    if not s.cod_enabled then
      problems := problems || '{"kind": "cod_off"}';
    else
      codfee := s.cod_fee;
      if subtotal - discount + shipping + codfee > s.cod_max then
        problems := problems || jsonb_build_object('kind', 'cod_limit', 'cod_max', s.cod_max);
      end if;
    end if;
  end if;

  return jsonb_build_object(
    'lines', lines, 'subtotal', subtotal, 'discount', discount, 'shipping', shipping, 'cod_fee', codfee,
    'total', subtotal - discount + shipping + codfee, 'coupon', coupon, 'method', p_method,
    'cod_available', s.cod_enabled and subtotal - discount + shipping + s.cod_fee <= s.cod_max,
    'problems', problems);
end $$;

-- Anyone can ask for a quote (it only reveals public prices, stock levels and whether a code works).
create function public.quote_checkout(p_items jsonb, p_coupon text default null, p_method text default 'razorpay')
returns jsonb language sql stable security definer set search_path = '' as $$
  select public.price_cart(p_items, p_coupon, p_method)
$$;

-- ---------------------------------------------------------------- stock holds

create function public.restock_order(p_order text, p_reason text) returns void
language plpgsql security definer set search_path = '' as $$
declare l record;
begin
  perform set_config('vertu.stock_reason', p_reason, true);
  for l in select sku, qty from public.order_items where order_id = p_order order by sku loop
    update public.products set stock = stock + l.qty where id = l.sku;
  end loop;
  perform set_config('vertu.stock_reason', '', true);
end $$;

-- Unpaid online orders give their stock back after the hold (default 15 minutes).
create function public.release_expired_orders() returns int
language plpgsql security definer set search_path = '' as $$
declare o record; n int := 0;
begin
  for o in select id, coupon_code from public.orders
           where payment_status = 'awaiting' and expires_at < now()
           order by id for update skip locked loop
    perform public.restock_order(o.id, 'released');
    if o.coupon_code is not null then
      update public.coupons set used_count = greatest(used_count - 1, 0) where code = o.coupon_code;
    end if;
    perform set_config('vertu.system', 'yes', true);
    update public.orders set payment_status = 'expired', status = 'Cancelled' where id = o.id;
    perform set_config('vertu.system', '', true);
    n := n + 1;
  end loop;
  return n;
end $$;

-- ---------------------------------------------------------------- creating orders (server only)

create function public.create_order(
  p_items jsonb, p_coupon text, p_method text, p_contact jsonb, p_address jsonb, p_user uuid default null)
returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  q jsonb;
  s public.settings;
  oid text;
  token uuid;
  l jsonb;
  email text := lower(trim(coalesce(p_contact ->> 'email', '')));
  phone text := coalesce(p_contact ->> 'phone', '');
  hold timestamptz;
begin
  perform public.release_expired_orders();

  if email !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' or char_length(email) > 254 then
    return jsonb_build_object('ok', false, 'error', 'bad_email');
  end if;
  if phone !~ '^\+91[6-9][0-9]{9}$' then
    return jsonb_build_object('ok', false, 'error', 'bad_phone');
  end if;
  if coalesce(trim(p_address ->> 'full_name'), '') = '' or coalesce(trim(p_address ->> 'line1'), '') = ''
     or coalesce(trim(p_address ->> 'city'), '') = '' or coalesce(trim(p_address ->> 'state'), '') = ''
     or coalesce(p_address ->> 'pin', '') !~ '^[1-9][0-9]{5}$' then
    return jsonb_build_object('ok', false, 'error', 'bad_address');
  end if;

  -- Lock every product in the bag (in a fixed order, so two checkouts can't deadlock), then price.
  perform 1 from public.products
    where id in (select value ->> 'sku' from jsonb_array_elements(p_items)) order by id for update;
  q := public.price_cart(p_items, p_coupon, p_method);
  if jsonb_array_length(q -> 'problems') > 0 then
    return jsonb_build_object('ok', false, 'error', 'cart', 'quote', q);
  end if;
  if p_coupon is not null and trim(p_coupon) <> '' and not coalesce((q -> 'coupon' ->> 'valid')::bool, false) then
    return jsonb_build_object('ok', false, 'error', 'coupon', 'quote', q);
  end if;
  if (q ->> 'total')::int < 1 then
    return jsonb_build_object('ok', false, 'error', 'zero_total', 'quote', q);
  end if;

  select * into s from public.settings where id = 1;
  hold := case when p_method = 'razorpay' then now() + make_interval(mins => s.hold_minutes) end;

  insert into public.orders (
    status, customer_id, customer_name, customer_email, customer_phone,
    ship_address, ship_city, ship_state, ship_pin, note,
    subtotal, discount, shipping, cod_fee, total, coupon_code,
    payment_method, payment_status, expires_at)
  values (
    'Pending', p_user, left(trim(p_address ->> 'full_name'), 120), email, phone,
    left(trim(p_address ->> 'line1') || coalesce(nullif(', ' || trim(coalesce(p_address ->> 'line2', '')), ', '), ''), 400),
    left(trim(p_address ->> 'city'), 80), left(trim(p_address ->> 'state'), 60), p_address ->> 'pin',
    left(coalesce(p_contact ->> 'note', ''), 500),
    (q ->> 'subtotal')::int, (q ->> 'discount')::int, (q ->> 'shipping')::int, (q ->> 'cod_fee')::int, (q ->> 'total')::int,
    case when coalesce((q -> 'coupon' ->> 'valid')::bool, false) then q -> 'coupon' ->> 'code' end,
    p_method, case when p_method = 'cod' then 'cod' else 'awaiting' end, hold)
  returning id, access_token into oid, token;

  perform set_config('vertu.stock_reason', 'order', true);
  for l in select value from jsonb_array_elements(q -> 'lines') loop
    insert into public.order_items (order_id, sku, category, colour, price, qty)
    values (oid, l ->> 'sku', l ->> 'category', l ->> 'colour', (l ->> 'price')::int, (l ->> 'qty')::int);
    update public.products set stock = stock - (l ->> 'qty')::int where id = l ->> 'sku';
  end loop;
  perform set_config('vertu.stock_reason', '', true);

  if coalesce((q -> 'coupon' ->> 'valid')::bool, false) then
    update public.coupons set used_count = used_count + 1 where code = q -> 'coupon' ->> 'code';
  end if;

  return jsonb_build_object('ok', true, 'order_id', oid, 'access_token', token, 'total', (q ->> 'total')::int,
                            'method', p_method, 'expires_at', hold, 'quote', q);
end $$;

create function public.attach_razorpay_order(p_order text, p_rzp_order text) returns void
language sql security definer set search_path = '' as $$
  update public.orders set razorpay_order_id = p_rzp_order where id = p_order and payment_status = 'awaiting'
$$;

-- Payment confirmed (by the browser's signed response or by Razorpay's webhook). Safe to call twice.
create function public.mark_order_paid(p_rzp_order text, p_payment text, p_amount_paise bigint)
returns jsonb
language plpgsql security definer set search_path = '' as $$
declare o public.orders; short text := null; l record;
begin
  select * into o from public.orders where razorpay_order_id = p_rzp_order for update;
  if o.id is null then return jsonb_build_object('ok', false, 'error', 'unknown_order'); end if;
  if o.payment_status in ('paid', 'refunded', 'partially_refunded') then
    return jsonb_build_object('ok', true, 'order_id', o.id, 'already', true);
  end if;
  if p_amount_paise is not null and p_amount_paise <> o.total::bigint * 100 then
    update public.orders set flag = 'amount_mismatch: paid ' || p_amount_paise || ' paise, expected ' || o.total * 100 where id = o.id;
    return jsonb_build_object('ok', false, 'error', 'amount_mismatch', 'order_id', o.id);
  end if;

  -- Paid after the hold ran out: take the stock again if it is still there; otherwise flag for a refund.
  if o.payment_status in ('expired', 'failed', 'cancelled') then
    for l in select i.sku, i.qty, p.stock from public.order_items i join public.products p on p.id = i.sku
             where i.order_id = o.id order by i.sku for update of p loop
      if l.stock < l.qty then short := coalesce(short || ', ', '') || l.sku; end if;
    end loop;
    if short is null then
      perform set_config('vertu.stock_reason', 'order', true);
      update public.products p set stock = p.stock - i.qty from public.order_items i where i.order_id = o.id and p.id = i.sku;
      perform set_config('vertu.stock_reason', '', true);
    end if;
  end if;

  perform set_config('vertu.system', 'yes', true);
  update public.orders set
    status = case when status = 'Cancelled' then 'Pending' else status end,
    payment_status = 'paid', razorpay_payment_id = p_payment, paid_at = now(), expires_at = null,
    flag = case when short is not null then 'paid_after_hold_out_of_stock: ' || short end
  where id = o.id;
  perform set_config('vertu.system', '', true);
  return jsonb_build_object('ok', true, 'order_id', o.id, 'flag', short);
end $$;

create function public.mark_order_failed(p_rzp_order text, p_reason text default '') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare o public.orders;
begin
  select * into o from public.orders where razorpay_order_id = p_rzp_order for update;
  if o.id is null then return jsonb_build_object('ok', false, 'error', 'unknown_order'); end if;
  -- A failed attempt doesn't end the order: the shopper can retry until the hold expires.
  if o.payment_status = 'awaiting' then
    update public.orders set note = left(trim(note || ' ' || 'Payment attempt failed: ' || coalesce(p_reason, '')), 500) where id = o.id;
  end if;
  return jsonb_build_object('ok', true, 'order_id', o.id);
end $$;

-- Cancel and/or record a refund (the server function calls Razorpay first, then this).
create function public.settle_cancel_refund(
  p_order text, p_refund_paise bigint, p_refund_id text, p_restock bool, p_cancel bool, p_actor uuid, p_reason text)
returns jsonb
language plpgsql security definer set search_path = '' as $$
declare o public.orders; refunded int;
begin
  select * into o from public.orders where id = p_order for update;
  if o.id is null then return jsonb_build_object('ok', false, 'error', 'unknown_order'); end if;
  refunded := o.refunded_amount + coalesce(p_refund_paise, 0)::int / 100;
  if refunded > coalesce(o.total, 0) then return jsonb_build_object('ok', false, 'error', 'refund_too_large'); end if;
  if p_restock and o.status <> 'Cancelled' then perform public.restock_order(o.id, case when p_cancel then 'cancelled' else 'return' end); end if;
  if p_cancel and o.status <> 'Cancelled' and o.coupon_code is not null and o.payment_status in ('awaiting', 'cod') then
    update public.coupons set used_count = greatest(used_count - 1, 0) where code = o.coupon_code;
  end if;
  perform set_config('vertu.system', 'yes', true);
  update public.orders set
    refunded_amount = refunded,
    status = case when p_cancel then 'Cancelled' else status end,
    payment_status = case
      when refunded > 0 and refunded >= total then 'refunded'
      when refunded > 0 then 'partially_refunded'
      when p_cancel and payment_status in ('awaiting', 'cod') then 'cancelled'
      else payment_status end,
    note = left(trim(note || ' ' || coalesce(nullif(p_reason, ''), '') ||
           case when p_refund_id is not null then ' [refund ' || p_refund_id || ']' else '' end), 500)
  where id = o.id;
  perform set_config('vertu.system', '', true);
  insert into public.audit_log (actor, action, entity, entity_id, changes)
  values (p_actor, case when p_cancel then 'cancel' else 'refund' end, 'orders', o.id,
          jsonb_build_object('refund_rupees', coalesce(p_refund_paise, 0) / 100, 'restock', p_restock, 'reason', p_reason));
  return jsonb_build_object('ok', true, 'order_id', o.id, 'refunded_amount', refunded);
end $$;

-- ---------------------------------------------------------------- shoppers looking at their order

-- The confirmation page knows the order id and its secret token (given only to the buyer).
create function public.order_lookup(p_id text, p_token uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'id', o.id, 'created_at', o.created_at, 'status', o.status, 'payment_status', o.payment_status,
    'payment_method', o.payment_method, 'expires_at', o.expires_at,
    'name', o.customer_name, 'email', o.customer_email, 'city', o.ship_city, 'pin', o.ship_pin,
    'subtotal', o.subtotal, 'discount', o.discount, 'shipping', o.shipping, 'cod_fee', o.cod_fee, 'total', o.total,
    'refunded_amount', o.refunded_amount,
    'lines', (select coalesce(jsonb_agg(jsonb_build_object('sku', sku, 'category', category, 'colour', colour, 'price', price, 'qty', qty) order by id), '[]')
              from public.order_items where order_id = o.id))
  from public.orders o where o.id = p_id and o.access_token = p_token
$$;

-- After signing in, orders placed as a guest with the same (verified) email join the account.
create function public.claim_my_orders() returns int
language plpgsql security definer set search_path = '' as $$
declare n int;
begin
  if auth.uid() is null or coalesce(auth.email(), '') = '' then return 0; end if;
  update public.orders set customer_id = auth.uid()
  where customer_id is null and lower(customer_email) = lower(auth.email());
  get diagnostics n = row_count;
  return n;
end $$;

-- ---------------------------------------------------------------- who may call what

revoke execute on function public.price_cart(jsonb, text, text), public.restock_order(text, text),
  public.release_expired_orders(), public.create_order(jsonb, text, text, jsonb, jsonb, uuid),
  public.attach_razorpay_order(text, text), public.mark_order_paid(text, text, bigint),
  public.mark_order_failed(text, text), public.settle_cancel_refund(text, bigint, text, bool, bool, uuid, text)
  from public, anon, authenticated;
grant execute on function public.price_cart(jsonb, text, text), public.release_expired_orders(),
  public.create_order(jsonb, text, text, jsonb, jsonb, uuid), public.attach_razorpay_order(text, text),
  public.mark_order_paid(text, text, bigint), public.mark_order_failed(text, text),
  public.settle_cancel_refund(text, bigint, text, bool, bool, uuid, text), public.restock_order(text, text)
  to service_role;
revoke execute on function public.claim_my_orders() from public, anon;

-- Postgres lets PUBLIC run new functions by default, so "revoke from anon" alone is not enough.
-- Tighten the Phase 1 team functions too (they already refuse non-owners inside; this closes the door earlier).
revoke execute on function public.team_list(), public.team_grant(text, text), public.team_revoke(uuid), public.activity(int)
  from public, anon;
grant execute on function public.team_list(), public.team_grant(text, text), public.team_revoke(uuid), public.activity(int)
  to authenticated;

-- Staff still only change status and note by hand; payment columns are set by the functions above.

-- ---------------------------------------------------------------- housekeeping job (optional but recommended)
-- Releases expired holds every 5 minutes. Checkout also does this itself, so the store works without it.
do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron;
    perform cron.schedule('vertu-release-holds', '*/5 * * * *', 'select public.release_expired_orders()');
  end if;
exception when others then
  raise notice 'pg_cron not scheduled (%). Enable it under Database -> Extensions, then run: select cron.schedule(''vertu-release-holds'', ''*/5 * * * *'', ''select public.release_expired_orders()'');', sqlerrm;
end $$;


-- ===== 20261112030000_phase4_emails.sql
-- VERTU Phase 4: email notifications.
--
-- Pattern: an "outbox". Whenever something email-worthy happens, the same database change writes a row
-- into email_outbox (so an email can never be lost or sent twice: dedupe_key is unique). The send-emails
-- Edge Function picks rows up every minute, renders them and sends them through Resend, retrying with backoff.

-- ---------------------------------------------------------------- settings and tracking

alter table public.settings
  add column notify_email           text check (notify_email is null or notify_email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  add column abandoned_cart_enabled bool not null default false;

alter table public.orders
  add column courier         text check (char_length(courier) <= 60),
  add column tracking_number text check (char_length(tracking_number) <= 60),
  add column tracking_url    text check (tracking_url is null or tracking_url ~ '^https?://');
grant update (courier, tracking_number, tracking_url) on public.orders to authenticated;

-- ---------------------------------------------------------------- outbox

create table public.email_outbox (
  id            bigint generated always as identity primary key,
  created_at    timestamptz not null default now(),
  kind          text not null,
  to_email      text not null check (to_email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  payload       jsonb not null default '{}'::jsonb,
  dedupe_key    text not null unique,
  related_order text,
  status        text not null default 'pending' check (status in ('pending', 'sending', 'sent', 'failed', 'skipped')),
  attempts      int  not null default 0,
  send_after    timestamptz not null default now(),
  sent_at       timestamptz,
  last_error    text,
  provider_id   text
);
create index email_outbox_due_idx on public.email_outbox (send_after) where status = 'pending';
create index email_outbox_order_idx on public.email_outbox (related_order);
alter table public.email_outbox enable row level security;
create policy "outbox admin read" on public.email_outbox for select using (public.is_admin());
revoke insert, update, delete on public.email_outbox from anon, authenticated;

create function public.enqueue_email(p_kind text, p_to text, p_payload jsonb, p_key text, p_delay interval default '0 seconds')
returns void
language plpgsql security definer set search_path = '' as $$
begin
  if coalesce(trim(p_to), '') = '' or p_to !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' then return; end if;
  insert into public.email_outbox (kind, to_email, payload, dedupe_key, related_order, send_after)
  values (p_kind, lower(trim(p_to)), coalesce(p_payload, '{}'::jsonb), p_key, p_payload ->> 'order_id', now() + p_delay)
  on conflict (dedupe_key) do nothing;
end $$;

-- Everything an order email needs, in one object.
create function public.order_email_payload(p_id text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'order_id', o.id, 'token', o.access_token, 'name', o.customer_name, 'email', o.customer_email,
    'created_at', o.created_at, 'status', o.status, 'payment_method', o.payment_method, 'payment_status', o.payment_status,
    'subtotal', o.subtotal, 'discount', o.discount, 'shipping', o.shipping, 'cod_fee', o.cod_fee, 'total', o.total,
    'refunded_amount', o.refunded_amount, 'coupon', o.coupon_code, 'phone', o.customer_phone,
    'address', jsonb_build_object('line', o.ship_address, 'city', o.ship_city, 'state', o.ship_state, 'pin', o.ship_pin),
    'courier', o.courier, 'tracking_number', o.tracking_number, 'tracking_url', o.tracking_url, 'flag', o.flag,
    'lines', (select coalesce(jsonb_agg(jsonb_build_object('sku', i.sku, 'name', coalesce(c.unit, i.category), 'colour', i.colour,
                                                           'price', i.price, 'qty', i.qty) order by i.id), '[]')
              from public.order_items i left join public.categories c on c.id = i.category where i.order_id = o.id))
  from public.orders o where o.id = p_id
$$;

-- ---------------------------------------------------------------- order emails (customer + store)

create function public.orders_notify() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  s public.settings;
  confirmed bool := false;
  p jsonb;
begin
  select * into s from public.settings where id = 1;
  if tg_op = 'INSERT' then
    confirmed := new.payment_status = 'cod';
  else
    confirmed := new.payment_status = 'paid' and old.payment_status in ('awaiting', 'expired', 'failed', 'cancelled');
  end if;
  p := public.order_email_payload(new.id);

  if confirmed then
    perform public.enqueue_email('order_confirmed', new.customer_email, p, 'order_confirmed:' || new.id);
    perform public.enqueue_email('admin_new_order', s.notify_email, p, 'admin_new_order:' || new.id);
  end if;

  if tg_op = 'UPDATE' then
    if new.status is distinct from old.status then
      if new.status = 'Shipped' then
        perform public.enqueue_email('order_shipped', new.customer_email, p, 'order_shipped:' || new.id);
      elsif new.status = 'Delivered' then
        perform public.enqueue_email('order_delivered', new.customer_email, p, 'order_delivered:' || new.id);
      elsif new.status = 'Cancelled' and old.payment_status not in ('awaiting', 'expired', 'failed') then
        -- (abandoned online checkouts expire quietly; nothing to tell the shopper)
        perform public.enqueue_email('order_cancelled', new.customer_email, p, 'order_cancelled:' || new.id);
      end if;
    end if;
    if new.refunded_amount > old.refunded_amount and not (new.status = 'Cancelled' and old.status <> 'Cancelled') then
      perform public.enqueue_email('order_refunded', new.customer_email,
        p || jsonb_build_object('refund', new.refunded_amount - old.refunded_amount),
        'order_refunded:' || new.id || ':' || new.refunded_amount);
    end if;
    if new.flag is not null and new.flag is distinct from old.flag then
      perform public.enqueue_email('admin_attention', s.notify_email, p, 'admin_attention:' || new.id || ':' || md5(new.flag));
    end if;
  end if;
  return new;
end $$;

create trigger orders_notify after update on public.orders
  for each row execute function public.orders_notify();
-- New orders are announced when the transaction commits, once their items have been written.
create constraint trigger orders_notify_new after insert on public.orders
  deferrable initially deferred
  for each row execute function public.orders_notify();

-- ---------------------------------------------------------------- stock emails

create function public.products_notify() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  s public.settings;
  a record;
  unit text;
begin
  select * into s from public.settings where id = 1;
  select c.unit into unit from public.categories c where c.id = new.category;

  -- A sold-out (or hidden) colour is back: write once to everyone who asked.
  if new.status = 'active' and new.stock > 0 and (old.stock <= 0 or old.status <> 'active') then
    for a in select id, email from public.stock_alerts where sku = new.id and notified_at is null order by id loop
      perform public.enqueue_email('back_in_stock', a.email,
        jsonb_build_object('sku', new.id, 'category', new.category, 'name', unit, 'colour', new.colour, 'price', new.price, 'stock', new.stock),
        'back_in_stock:' || a.id);
      update public.stock_alerts set notified_at = now() where id = a.id;
    end loop;
  end if;

  -- Crossing the low-stock line tells the store (at most once a day per colour).
  if new.status = 'active' and old.stock > s.low_stock and new.stock <= s.low_stock then
    perform public.enqueue_email('admin_low_stock', s.notify_email,
      jsonb_build_object('sku', new.id, 'name', unit, 'colour', new.colour, 'stock', new.stock, 'threshold', s.low_stock),
      'admin_low_stock:' || new.id || ':' || to_char(now() at time zone 'Asia/Kolkata', 'YYYY-MM-DD'));
  end if;
  return new;
end $$;

create trigger products_notify after update of stock, status on public.products
  for each row execute function public.products_notify();

-- ---------------------------------------------------------------- newsletter (double opt-in)

create table public.newsletter_subscribers (
  email           text primary key check (email = lower(email) and email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  status          text not null default 'pending' check (status in ('pending', 'subscribed', 'unsubscribed')),
  token           uuid not null unique default gen_random_uuid(),
  source          text not null default '',
  created_at      timestamptz not null default now(),
  confirmed_at    timestamptz,
  unsubscribed_at timestamptz
);
alter table public.newsletter_subscribers enable row level security;
create policy "subscribers owner read" on public.newsletter_subscribers for select using (public.is_owner());
revoke insert, update, delete on public.newsletter_subscribers from anon, authenticated;

-- Always answers { ok: true } so the form can't be used to find out who is subscribed.
create function public.subscribe_newsletter(p_email text, p_source text default 'footer') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  e text := lower(trim(coalesce(p_email, '')));
  sub public.newsletter_subscribers;
begin
  if e !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' or char_length(e) > 254 then
    return jsonb_build_object('ok', false, 'error', 'bad_email');
  end if;
  insert into public.newsletter_subscribers (email, source) values (e, left(coalesce(p_source, ''), 40))
  on conflict (email) do update set
    status = case when newsletter_subscribers.status = 'subscribed' then 'subscribed' else 'pending' end,
    unsubscribed_at = null
  returning * into sub;
  if sub.status = 'pending' then
    perform public.enqueue_email('newsletter_confirm', e, jsonb_build_object('token', sub.token),
      'newsletter_confirm:' || e || ':' || to_char(now() at time zone 'Asia/Kolkata', 'YYYY-MM-DD'));
  end if;
  return jsonb_build_object('ok', true);
end $$;

create function public.confirm_newsletter(p_token uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare sub public.newsletter_subscribers;
begin
  update public.newsletter_subscribers set status = 'subscribed', confirmed_at = coalesce(confirmed_at, now()), unsubscribed_at = null
  where token = p_token and status <> 'unsubscribed' returning * into sub;
  if sub.email is null then return jsonb_build_object('ok', false); end if;
  update public.profiles p set marketing_opt_in = true from auth.users u where u.id = p.id and lower(u.email) = sub.email and not p.marketing_opt_in;
  return jsonb_build_object('ok', true);
end $$;

create function public.unsubscribe_newsletter(p_token uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare sub public.newsletter_subscribers;
begin
  update public.newsletter_subscribers set status = 'unsubscribed', unsubscribed_at = now()
  where token = p_token returning * into sub;
  if sub.email is null then return jsonb_build_object('ok', false); end if;
  update public.profiles p set marketing_opt_in = false from auth.users u where u.id = p.id and lower(u.email) = sub.email and p.marketing_opt_in;
  return jsonb_build_object('ok', true);
end $$;

-- The account's "email me about launches" box and the newsletter list stay in step.
-- (Signed-in emails are already verified, so no confirmation email is needed.)
create function public.profiles_marketing_sync() returns trigger
language plpgsql security definer set search_path = '' as $$
declare e text;
begin
  select lower(email) into e from auth.users where id = new.id;
  if e is null then return new; end if;
  if new.marketing_opt_in then
    insert into public.newsletter_subscribers (email, status, source, confirmed_at) values (e, 'subscribed', 'account', now())
    on conflict (email) do update set status = 'subscribed', confirmed_at = coalesce(newsletter_subscribers.confirmed_at, now()), unsubscribed_at = null
    where newsletter_subscribers.status <> 'subscribed';
  else
    update public.newsletter_subscribers set status = 'unsubscribed', unsubscribed_at = now() where email = e and status <> 'unsubscribed';
  end if;
  return new;
end $$;
create trigger profiles_marketing_sync after update of marketing_opt_in on public.profiles
  for each row when (old.marketing_opt_in is distinct from new.marketing_opt_in)
  execute function public.profiles_marketing_sync();

-- ---------------------------------------------------------------- abandoned bags (opt-in only)

-- Signed-in shoppers who agreed to marketing emails, whose saved bag hasn't changed for 3 hours and who
-- haven't ordered since: one gentle reminder per bag per day. Off unless switched on in Settings.
create function public.queue_abandoned_carts() returns int
language plpgsql security definer set search_path = '' as $$
declare r record; items jsonb; n int := 0;
begin
  if not (select abandoned_cart_enabled from public.settings where id = 1) then return 0; end if;
  for r in
    select c.user_id, c.items, c.updated_at, u.email, coalesce(nullif(p.full_name, ''), '') as name, ns.token
    from public.carts c
    join auth.users u on u.id = c.user_id
    join public.profiles p on p.id = c.user_id and p.marketing_opt_in
    join public.newsletter_subscribers ns on ns.email = lower(u.email) and ns.status = 'subscribed'
    where jsonb_array_length(c.items) > 0
      and c.updated_at < now() - interval '3 hours' and c.updated_at > now() - interval '48 hours'
      and not exists (select 1 from public.orders o where o.customer_id = c.user_id and o.created_at > c.updated_at - interval '5 minutes')
  loop
    select coalesce(jsonb_agg(jsonb_build_object('sku', pr.id, 'name', cat.unit, 'colour', pr.colour, 'price', pr.price, 'qty', (i ->> 'qty')::int)), '[]')
      into items
    from jsonb_array_elements(r.items) i
    join public.products pr on pr.id = i ->> 'sku' and pr.status = 'active' and pr.stock > 0
    join public.categories cat on cat.id = pr.category;
    if jsonb_array_length(items) = 0 then continue; end if;
    perform public.enqueue_email('abandoned_cart', r.email,
      jsonb_build_object('name', r.name, 'items', items, 'unsubscribe', r.token),
      'abandoned_cart:' || r.user_id || ':' || to_char(r.updated_at at time zone 'Asia/Kolkata', 'YYYY-MM-DD'));
    n := n + 1;
  end loop;
  return n;
end $$;

-- ---------------------------------------------------------------- the sender's side (service role only)

create function public.claim_outbox(p_limit int default 20) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare rows jsonb;
begin
  -- emails that waited more than 3 days (e.g. before email was set up) would arrive stale: skip them
  update public.email_outbox set status = 'skipped', last_error = 'too old to send'
  where status = 'pending' and created_at < now() - interval '3 days';
  -- a sender that crashed mid-send leaves rows in 'sending': try them again after 10 minutes
  update public.email_outbox set status = 'pending'
  where status = 'sending' and send_after < now() - interval '10 minutes';

  with picked as (
    select id from public.email_outbox
    where status = 'pending' and send_after <= now()
    order by id limit least(greatest(p_limit, 1), 100)
    for update skip locked
  ), claimed as (
    update public.email_outbox e set status = 'sending', attempts = e.attempts + 1, send_after = now()
    from picked where e.id = picked.id
    returning e.id, e.kind, e.to_email, e.payload, e.attempts
  )
  select coalesce(jsonb_agg(jsonb_build_object('id', id, 'kind', kind, 'to', to_email, 'payload', payload, 'attempts', attempts) order by id), '[]')
    into rows from claimed;
  return rows;
end $$;

-- Success, or a failure that is retried after 2, 4, 8, 16 minutes before giving up.
create function public.complete_outbox(p_id bigint, p_ok bool, p_provider_id text default null, p_error text default null)
returns void
language plpgsql security definer set search_path = '' as $$
begin
  update public.email_outbox set
    status = case when p_ok then 'sent' when attempts >= 5 then 'failed' else 'pending' end,
    sent_at = case when p_ok then now() end,
    provider_id = coalesce(p_provider_id, provider_id),
    last_error = case when p_ok then null else left(p_error, 500) end,
    send_after = case when p_ok then send_after else now() + make_interval(mins => power(2, attempts)::int) end
  where id = p_id and status = 'sending';
end $$;

-- Owners can retry an email that failed.
create function public.retry_email(p_id bigint) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_owner() then raise exception 'not_allowed' using errcode = '42501'; end if;
  update public.email_outbox set status = 'pending', attempts = 0, send_after = now(), last_error = null
  where id = p_id and status in ('failed', 'skipped');
end $$;

-- ---------------------------------------------------------------- who may call what

revoke execute on function public.enqueue_email(text, text, jsonb, text, interval), public.order_email_payload(text),
  public.queue_abandoned_carts(), public.claim_outbox(int), public.complete_outbox(bigint, bool, text, text)
  from public, anon, authenticated;
grant execute on function public.enqueue_email(text, text, jsonb, text, interval), public.order_email_payload(text),
  public.queue_abandoned_carts(), public.claim_outbox(int), public.complete_outbox(bigint, bool, text, text)
  to service_role;
revoke execute on function public.retry_email(bigint) from public, anon;
grant execute on function public.retry_email(bigint) to authenticated;
-- subscribe / confirm / unsubscribe stay open to everyone (they only act on a valid email or a secret token)

-- ---------------------------------------------------------------- housekeeping job
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('vertu-abandoned-carts', '15 * * * *', 'select public.queue_abandoned_carts()');
  end if;
exception when others then
  raise notice 'abandoned-cart job not scheduled: %', sqlerrm;
end $$;


-- ===== 20261112040000_phase5_fulfilment.sql
-- VERTU Phase 5: shipping (Shiprocket), tracking, GST invoices, returns, delivery estimates.

-- ---------------------------------------------------------------- per-collection tax and parcel details

alter table public.categories
  add column hsn      text          not null default '4202' check (hsn ~ '^[0-9]{4,8}$'),
  add column gst_rate numeric(4, 2) not null default 18    check (gst_rate between 0 and 28),
  -- parcel for one bag, used to book couriers: kg and cm. Estimates: weigh a packed bag and update.
  add column package  jsonb not null default '{"weight": 0.5, "length": 30, "breadth": 10, "height": 25}'::jsonb
    check (jsonb_typeof(package) = 'object');
update public.categories set package = '{"weight": 0.6, "length": 32, "breadth": 12, "height": 28}' where id = 'sling';
update public.categories set package = '{"weight": 0.4, "length": 26, "breadth": 8, "height": 30}' where id = 'mens';
update public.categories set package = '{"weight": 1.0, "length": 42, "breadth": 14, "height": 34}' where id = 'laptop';

-- ---------------------------------------------------------------- business and shipping settings

alter table public.settings
  add column pickup_location    text not null default 'Primary' check (char_length(pickup_location) between 1 and 60),
  add column pickup_pin         text check (pickup_pin is null or pickup_pin ~ '^[1-9][0-9]{5}$'),
  add column legal_name         text not null default '' check (char_length(legal_name) <= 120),
  add column gstin              text check (gstin is null or gstin ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$'),
  add column business_address   text not null default '' check (char_length(business_address) <= 300),
  add column business_state     text not null default '' check (char_length(business_state) <= 60),
  add column business_city      text not null default '' check (char_length(business_city) <= 80),
  add column business_phone     text check (business_phone is null or business_phone ~ '^\+91[6-9][0-9]{9}$'),
  add column gst_registered     bool not null default false,
  add column invoice_prefix     text not null default 'VRT' check (invoice_prefix ~ '^[A-Z0-9]{1,6}$'),
  add column return_window_days int  not null default 7 check (return_window_days between 0 and 60);

create or replace function public.store_rules() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('shipping_fee', shipping_fee, 'free_shipping_over', free_shipping_over,
    'cod_enabled', cod_enabled, 'cod_fee', cod_fee, 'cod_max', cod_max, 'return_window_days', return_window_days)
  from public.settings where id = 1
$$;

-- ---------------------------------------------------------------- shipments and tracking

alter table public.orders
  add column delivered_at        timestamptz,
  add column shiprocket_order_id text,
  add column shipment_id         text,
  add column awb                 text unique,
  add column label_url           text check (label_url is null or label_url ~ '^https?://'),
  add column ship_status         text,
  add column ship_status_at      timestamptz,
  add column eta                 date;

create function public.orders_delivered_at() returns trigger
language plpgsql set search_path = '' as $$
begin
  if new.status = 'Delivered' and old.status <> 'Delivered' then new.delivered_at := coalesce(new.delivered_at, now()); end if;
  return new;
end $$;
create trigger orders_delivered_at before update of status on public.orders
  for each row execute function public.orders_delivered_at();

create table public.shipment_events (
  id        bigint generated always as identity primary key,
  order_id  text references public.orders (id) on delete cascade,
  return_id bigint,
  awb       text not null,
  at        timestamptz not null,
  status    text not null,
  location  text not null default '',
  raw       jsonb,
  unique (awb, at, status)
);
create index shipment_events_order_idx on public.shipment_events (order_id, at desc);
alter table public.shipment_events enable row level security;
create policy "shipment events admin read" on public.shipment_events for select using (public.is_admin());
create policy "shipment events own read" on public.shipment_events for select
  using (exists (select 1 from public.orders o where o.id = order_id and o.customer_id = auth.uid()));

-- Called after a shipment is booked with Shiprocket (server only).
create function public.record_shipment(p_order text, p_sr_order text, p_shipment text, p_awb text, p_courier text, p_label text)
returns jsonb
language plpgsql security definer set search_path = '' as $$
declare o public.orders;
begin
  select * into o from public.orders where id = p_order for update;
  if o.id is null then return jsonb_build_object('ok', false, 'error', 'unknown_order'); end if;
  perform set_config('vertu.system', 'yes', true);
  update public.orders set
    shiprocket_order_id = p_sr_order, shipment_id = p_shipment, awb = nullif(p_awb, ''),
    courier = coalesce(nullif(p_courier, ''), courier), tracking_number = coalesce(nullif(p_awb, ''), tracking_number),
    tracking_url = case when coalesce(p_awb, '') <> '' then 'https://shiprocket.co/tracking/' || p_awb else tracking_url end,
    label_url = coalesce(p_label, label_url),
    ship_status = case when coalesce(p_awb, '') = '' then 'BOOKED' else 'AWB ASSIGNED' end,
    ship_status_at = null, -- only courier events set the time
    status = case when status = 'Pending' and coalesce(p_awb, '') <> '' then 'Processing' else status end
  where id = p_order;
  perform set_config('vertu.system', '', true);
  return jsonb_build_object('ok', true, 'order_id', p_order);
end $$;

create function public.clear_shipment(p_order text, p_reason text default '') returns void
language plpgsql security definer set search_path = '' as $$
begin
  update public.orders set shiprocket_order_id = null, shipment_id = null, awb = null, label_url = null,
    tracking_number = null, tracking_url = null, ship_status = 'SHIPMENT CANCELLED', ship_status_at = null,
    note = left(trim(note || ' Shipment cancelled. ' || coalesce(p_reason, '')), 500)
  where id = p_order and status in ('Pending', 'Processing');
end $$;

-- Courier tracking updates (Shiprocket webhook). Moves the order along and raises flags when deliveries go wrong.
create function public.apply_tracking(p_awb text, p_status text, p_at timestamptz, p_location text, p_etd timestamptz, p_is_return bool, p_raw jsonb)
returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  o public.orders;
  r record;
  st text := upper(regexp_replace(trim(coalesce(p_status, '')), '\s+', ' ', 'g'));
  at timestamptz := coalesce(p_at, now());
  moved text := null;
begin
  if st = '' or coalesce(p_awb, '') = '' then return jsonb_build_object('ok', false, 'error', 'bad_event'); end if;

  if p_is_return then
    select * into r from public.return_requests where return_awb = p_awb for update;
    if r.id is null then return jsonb_build_object('ok', false, 'error', 'unknown_awb'); end if;
    insert into public.shipment_events (order_id, return_id, awb, at, status, location, raw)
    values (r.order_id, r.id, p_awb, at, st, left(coalesce(p_location, ''), 120), p_raw) on conflict do nothing;
    if st = 'DELIVERED' and r.status in ('pickup_scheduled', 'in_transit') then
      update public.return_requests set status = 'arrived' where id = r.id;
    elsif st ~ '(PICKED UP|IN TRANSIT|SHIPPED|REACHED)' and r.status = 'pickup_scheduled' then
      update public.return_requests set status = 'in_transit' where id = r.id;
    end if;
    return jsonb_build_object('ok', true, 'return_id', r.id);
  end if;

  select * into o from public.orders where awb = p_awb for update;
  if o.id is null then return jsonb_build_object('ok', false, 'error', 'unknown_awb'); end if;
  insert into public.shipment_events (order_id, awb, at, status, location, raw)
  values (o.id, p_awb, at, st, left(coalesce(p_location, ''), 120), p_raw) on conflict do nothing;
  -- an older courier event arriving late is kept in the timeline but doesn't move the order backwards
  if o.ship_status_at is not null and at < o.ship_status_at then
    return jsonb_build_object('ok', true, 'order_id', o.id, 'stale', true);
  end if;

  perform set_config('vertu.system', 'yes', true);
  update public.orders set ship_status = st, ship_status_at = at, eta = coalesce(p_etd::date, eta) where id = o.id;
  if o.status <> 'Cancelled' then
    if st = 'DELIVERED' and o.status <> 'Delivered' then
      update public.orders set status = 'Delivered' where id = o.id;
      moved := 'Delivered';
    elsif st ~ '^(PICKED UP|SHIPPED|IN TRANSIT|OUT FOR DELIVERY|REACHED|DISPATCHED)' and o.status in ('Pending', 'Processing') then
      update public.orders set status = 'Shipped' where id = o.id;
      moved := 'Shipped';
    end if;
    if st = 'OUT FOR DELIVERY' then
      perform public.enqueue_email('order_out_for_delivery', o.customer_email, public.order_email_payload(o.id), 'order_out_for_delivery:' || o.id);
    end if;
    if st ~ '^RTO' then
      update public.orders set flag = 'returning_to_us: ' || lower(st) where id = o.id and flag is distinct from 'returning_to_us: ' || lower(st);
    elsif st ~ '(UNDELIVERED|NDR|DELIVERY FAILED|LOST|DAMAGED)' then
      update public.orders set flag = 'delivery_problem: ' || lower(st) where id = o.id and flag is distinct from 'delivery_problem: ' || lower(st);
    end if;
  end if;
  perform set_config('vertu.system', '', true);
  return jsonb_build_object('ok', true, 'order_id', o.id, 'moved', moved);
end $$;

-- ---------------------------------------------------------------- GST invoices

create table public.invoice_counters (fy text primary key, last int not null default 0);
alter table public.invoice_counters enable row level security;

create table public.invoices (
  id        bigint generated always as identity primary key,
  number    text not null unique,
  order_id  text not null unique references public.orders (id),
  fy        text not null,
  issued_at timestamptz not null default now(),
  total     numeric(12, 2) not null,
  data      jsonb not null
);
alter table public.invoices enable row level security;
create policy "invoices admin read" on public.invoices for select using (public.is_admin());
create policy "invoices own read" on public.invoices for select
  using (exists (select 1 from public.orders o where o.id = order_id and o.customer_id = auth.uid()));
revoke insert, update, delete on public.invoices, public.invoice_counters from anon, authenticated;

-- Indian financial year: April to March, e.g. 2026-11-12 -> '26-27'.
create function public.fy_of(p_ts timestamptz) returns text
language sql immutable set search_path = '' as $$
  select case when extract(month from p_ts at time zone 'Asia/Kolkata') >= 4
    then to_char(p_ts at time zone 'Asia/Kolkata', 'YY') || '-' || to_char((p_ts at time zone 'Asia/Kolkata') + interval '1 year', 'YY')
    else to_char((p_ts at time zone 'Asia/Kolkata') - interval '1 year', 'YY') || '-' || to_char(p_ts at time zone 'Asia/Kolkata', 'YY') end
$$;

-- Issues the tax invoice for an order (once). Prices are GST-inclusive, so tax is worked backwards:
-- taxable value = amount x 100 / (100 + rate). Discounts are spread over the lines in proportion.
-- Shipping and cash-on-delivery fees are charged with the goods (a composite supply) at the goods' rate.
create function public.issue_invoice(p_order text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  o public.orders; s public.settings; inv public.invoices;
  l record; lines jsonb := '[]'; n int; num text; f text;
  intra bool; reg bool; share numeric; left_discount numeric; gross numeric; net numeric; taxable numeric; tax numeric;
  rate numeric; top_rate numeric := 0; top_hsn text := '4202'; i int := 0; cnt int;
  t_taxable numeric := 0; t_cgst numeric := 0; t_sgst numeric := 0; t_igst numeric := 0; t_total numeric := 0;
  extra record;
begin
  select * into inv from public.invoices where order_id = p_order;
  if inv.id is not null then return jsonb_build_object('ok', true, 'number', inv.number, 'existing', true); end if;
  select * into o from public.orders where id = p_order for update;
  if o.id is null then return jsonb_build_object('ok', false, 'error', 'unknown_order'); end if;
  if o.payment_status not in ('paid', 'cod', 'partially_refunded') or o.status = 'Cancelled' then
    return jsonb_build_object('ok', false, 'error', 'not_invoiceable');
  end if;
  select * into s from public.settings where id = 1;
  if coalesce(s.legal_name, '') = '' then return jsonb_build_object('ok', false, 'error', 'seller_details_missing'); end if;
  reg := s.gst_registered and s.gstin is not null;
  intra := upper(trim(s.business_state)) = upper(trim(o.ship_state));
  left_discount := coalesce(o.discount, 0);
  select count(*) into cnt from public.order_items where order_id = o.id;

  for l in select it.*, c.unit, c.hsn, c.gst_rate from public.order_items it left join public.categories c on c.id = it.category
           where it.order_id = o.id order by it.id loop
    i := i + 1;
    gross := l.price * l.qty;
    share := case when i = cnt then left_discount else round(coalesce(o.discount, 0) * gross / nullif(o.subtotal, 0), 2) end;
    left_discount := left_discount - share;
    net := gross - share;
    rate := case when reg then coalesce(l.gst_rate, 18) else 0 end;
    if rate >= top_rate then top_rate := rate; top_hsn := coalesce(l.hsn, '4202'); end if;
    taxable := round(net * 100 / (100 + rate), 2);
    tax := net - taxable;
    lines := lines || jsonb_build_object(
      'description', l.colour || ' ' || coalesce(l.unit, l.category), 'sku', l.sku, 'hsn', coalesce(l.hsn, '4202'),
      'qty', l.qty, 'unit_price', l.price, 'gross', gross, 'discount', share, 'taxable', taxable, 'rate', rate,
      'cgst', case when reg and intra then round(tax / 2, 2) else 0 end,
      'sgst', case when reg and intra then tax - round(tax / 2, 2) else 0 end,
      'igst', case when reg and not intra then tax else 0 end, 'total', net);
    t_taxable := t_taxable + taxable; t_total := t_total + net;
    if reg and intra then t_cgst := t_cgst + round(tax / 2, 2); t_sgst := t_sgst + tax - round(tax / 2, 2);
    elsif reg then t_igst := t_igst + tax; end if;
  end loop;

  for extra in select * from (values ('Shipping and handling', o.shipping), ('Cash on delivery fee', o.cod_fee)) v(label, amount) where amount > 0 loop
    net := extra.amount;
    taxable := round(net * 100 / (100 + top_rate), 2);
    tax := net - taxable;
    lines := lines || jsonb_build_object('description', extra.label, 'sku', null, 'hsn', top_hsn, 'qty', 1, 'unit_price', net,
      'gross', net, 'discount', 0, 'taxable', taxable, 'rate', top_rate,
      'cgst', case when reg and intra then round(tax / 2, 2) else 0 end,
      'sgst', case when reg and intra then tax - round(tax / 2, 2) else 0 end,
      'igst', case when reg and not intra then tax else 0 end, 'total', net);
    t_taxable := t_taxable + taxable; t_total := t_total + net;
    if reg and intra then t_cgst := t_cgst + round(tax / 2, 2); t_sgst := t_sgst + tax - round(tax / 2, 2);
    elsif reg then t_igst := t_igst + tax; end if;
  end loop;

  f := public.fy_of(now());
  insert into public.invoice_counters (fy, last) values (f, 1)
  on conflict (fy) do update set last = invoice_counters.last + 1 returning last into n;
  num := s.invoice_prefix || '/' || f || '/' || lpad(n::text, 4, '0');

  insert into public.invoices (number, order_id, fy, total, data) values (num, o.id, f, t_total, jsonb_build_object(
    'title', case when reg then 'Tax invoice' else 'Invoice' end, 'number', num, 'date', now(), 'order_id', o.id,
    'order_date', o.created_at, 'registered', reg, 'intra_state', intra,
    'seller', jsonb_build_object('name', s.legal_name, 'gstin', s.gstin, 'address', s.business_address, 'state', s.business_state),
    'buyer', jsonb_build_object('name', o.customer_name, 'address', o.ship_address, 'city', o.ship_city, 'state', o.ship_state,
                                'pin', o.ship_pin, 'email', o.customer_email, 'phone', o.customer_phone),
    'place_of_supply', o.ship_state, 'payment_method', o.payment_method, 'lines', lines,
    'totals', jsonb_build_object('taxable', t_taxable, 'cgst', t_cgst, 'sgst', t_sgst, 'igst', t_igst, 'total', t_total)));
  return jsonb_build_object('ok', true, 'number', num);
end $$;

-- Staff can issue an invoice from the order panel; shipping an order issues it automatically.
create function public.create_invoice(p_order text) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_admin() then raise exception 'not_allowed' using errcode = '42501'; end if;
  return public.issue_invoice(p_order);
end $$;

create function public.orders_auto_invoice() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.status = 'Shipped' and old.status <> 'Shipped' then perform public.issue_invoice(new.id); end if;
  return new;
end $$;
create trigger orders_auto_invoice after update of status on public.orders
  for each row execute function public.orders_auto_invoice();

-- The buyer's copy, reached with the order's secret link.
create function public.invoice_lookup(p_id text, p_token uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select i.data from public.invoices i join public.orders o on o.id = i.order_id
  where o.id = p_id and o.access_token = p_token
$$;

-- ---------------------------------------------------------------- returns

create table public.return_requests (
  id            bigint generated always as identity primary key,
  order_id      text not null references public.orders (id) on delete cascade,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  items         jsonb not null check (jsonb_typeof(items) = 'array' and jsonb_array_length(items) between 1 and 20),
  reason        text not null check (reason in ('damaged', 'wrong_item', 'not_as_described', 'changed_mind', 'other')),
  details       text not null default '' check (char_length(details) <= 1000),
  status        text not null default 'requested'
                check (status in ('requested', 'approved', 'rejected', 'pickup_scheduled', 'in_transit', 'arrived', 'received', 'refunded', 'closed')),
  decided_at    timestamptz,
  decided_by    uuid,
  admin_note    text not null default '' check (char_length(admin_note) <= 500),
  return_awb    text unique,
  refund_amount int
);
create index return_requests_order_idx on public.return_requests (order_id);
create trigger return_requests_touch before update on public.return_requests
  for each row execute function public.touch_updated_at();
create trigger return_requests_audit after insert or update on public.return_requests
  for each row execute function public.audit('id');
alter table public.return_requests enable row level security;
create policy "returns admin read" on public.return_requests for select using (public.is_admin());
create policy "returns own read" on public.return_requests for select
  using (exists (select 1 from public.orders o where o.id = order_id and o.customer_id = auth.uid()));
revoke insert, update, delete on public.return_requests from anon, authenticated;

create function public.return_payload(p_id bigint) returns jsonb
language sql stable security definer set search_path = '' as $$
  select public.order_email_payload(r.order_id) || jsonb_build_object(
    'return_id', r.id, 'reason', r.reason, 'details', r.details, 'admin_note', r.admin_note, 'return_status', r.status,
    'return_items', (select coalesce(jsonb_agg(jsonb_build_object('sku', it ->> 'sku', 'qty', (it ->> 'qty')::int,
        'name', coalesce(c.unit, oi.category), 'colour', oi.colour, 'price', oi.price)), '[]')
      from jsonb_array_elements(r.items) it
      join public.order_items oi on oi.order_id = r.order_id and oi.sku = it ->> 'sku'
      left join public.categories c on c.id = oi.category))
  from public.return_requests r where r.id = p_id
$$;

-- Shoppers ask from their order page (secret link) or account. Delivered orders, within the return window.
create function public.request_return(p_order text, p_token uuid, p_items jsonb, p_reason text, p_details text default '')
returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  o public.orders; s public.settings; it jsonb; ordered int; already int; rid bigint; clean jsonb := '[]';
begin
  select * into o from public.orders where id = p_order
    and ((p_token is not null and access_token = p_token) or (auth.uid() is not null and customer_id = auth.uid()));
  if o.id is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  select * into s from public.settings where id = 1;
  if s.return_window_days = 0 then return jsonb_build_object('ok', false, 'error', 'returns_off'); end if;
  if o.status <> 'Delivered' then return jsonb_build_object('ok', false, 'error', 'not_delivered'); end if;
  if o.delivered_at < now() - make_interval(days => s.return_window_days) then
    return jsonb_build_object('ok', false, 'error', 'window_closed');
  end if;
  if p_reason not in ('damaged', 'wrong_item', 'not_as_described', 'changed_mind', 'other') then
    return jsonb_build_object('ok', false, 'error', 'bad_reason');
  end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then return jsonb_build_object('ok', false, 'error', 'bad_items'); end if;
  for it in select value from jsonb_array_elements(p_items) loop
    select coalesce(sum(qty), 0) into ordered from public.order_items where order_id = o.id and sku = it ->> 'sku';
    select coalesce(sum((x ->> 'qty')::int), 0) into already
      from public.return_requests rr, jsonb_array_elements(rr.items) x
      where rr.order_id = o.id and rr.status <> 'rejected' and x ->> 'sku' = it ->> 'sku';
    if ordered = 0 or coalesce((it ->> 'qty')::int, 0) < 1 or (it ->> 'qty')::int > ordered - already then
      return jsonb_build_object('ok', false, 'error', 'bad_items', 'sku', it ->> 'sku');
    end if;
    clean := clean || jsonb_build_object('sku', it ->> 'sku', 'qty', (it ->> 'qty')::int);
  end loop;
  insert into public.return_requests (order_id, items, reason, details)
  values (o.id, clean, p_reason, left(coalesce(p_details, ''), 1000)) returning id into rid;
  perform public.enqueue_email('return_requested', o.customer_email, public.return_payload(rid), 'return_requested:' || rid);
  perform public.enqueue_email('admin_return', s.notify_email, public.return_payload(rid), 'admin_return:' || rid);
  return jsonb_build_object('ok', true, 'id', rid);
end $$;

create function public.order_returns(p_id text, p_token uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'status', r.status, 'created_at', r.created_at, 'items', r.items,
    'reason', r.reason, 'admin_note', r.admin_note) order by r.id), '[]')
  from public.return_requests r join public.orders o on o.id = r.order_id
  where o.id = p_id and o.access_token = p_token
$$;

create function public.decide_return(p_id bigint, p_approve bool, p_note text default '') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare r public.return_requests; o public.orders;
begin
  if not public.is_admin() then raise exception 'not_allowed' using errcode = '42501'; end if;
  select * into r from public.return_requests where id = p_id for update;
  if r.id is null or r.status <> 'requested' then return jsonb_build_object('ok', false, 'error', 'not_open'); end if;
  update public.return_requests set status = case when p_approve then 'approved' else 'rejected' end,
    decided_at = now(), decided_by = auth.uid(), admin_note = left(coalesce(p_note, ''), 500) where id = p_id;
  select * into o from public.orders where id = r.order_id;
  perform public.enqueue_email(case when p_approve then 'return_approved' else 'return_rejected' end, o.customer_email,
    public.return_payload(p_id), 'return_decided:' || p_id);
  return jsonb_build_object('ok', true);
end $$;

create function public.set_return_pickup(p_id bigint, p_awb text) returns void
language sql security definer set search_path = '' as $$
  update public.return_requests set return_awb = p_awb, status = 'pickup_scheduled' where id = p_id and status = 'approved'
$$;

-- Items checked back in: restock exactly what came back, and suggest the refund (after the order's discount share).
create function public.receive_return(p_id bigint) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare r public.return_requests; o public.orders; it jsonb; amount numeric := 0; price int;
begin
  if not public.is_admin() then raise exception 'not_allowed' using errcode = '42501'; end if;
  select * into r from public.return_requests where id = p_id for update;
  if r.id is null or r.status not in ('approved', 'pickup_scheduled', 'in_transit', 'arrived') then
    return jsonb_build_object('ok', false, 'error', 'not_receivable');
  end if;
  select * into o from public.orders where id = r.order_id;
  perform set_config('vertu.stock_reason', 'return', true);
  for it in select value from jsonb_array_elements(r.items) loop
    update public.products set stock = stock + (it ->> 'qty')::int where id = it ->> 'sku';
    select oi.price into price from public.order_items oi where oi.order_id = r.order_id and oi.sku = it ->> 'sku' limit 1;
    amount := amount + price * (it ->> 'qty')::int;
  end loop;
  perform set_config('vertu.stock_reason', '', true);
  amount := floor(amount * (1 - coalesce(o.discount, 0)::numeric / nullif(o.subtotal, 0)));
  amount := least(amount, coalesce(o.total, 0) - coalesce(o.refunded_amount, 0));
  update public.return_requests set status = 'received', refund_amount = amount::int where id = p_id;
  return jsonb_build_object('ok', true, 'refund_amount', amount::int);
end $$;

create function public.close_return(p_id bigint, p_refunded bool) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_admin() then raise exception 'not_allowed' using errcode = '42501'; end if;
  update public.return_requests set status = case when p_refunded then 'refunded' else 'closed' end
  where id = p_id and status in ('received', 'approved', 'arrived');
end $$;

-- ---------------------------------------------------------------- order page: everything the buyer can see

create or replace function public.order_lookup(p_id text, p_token uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'id', o.id, 'created_at', o.created_at, 'status', o.status, 'payment_status', o.payment_status,
    'payment_method', o.payment_method, 'expires_at', o.expires_at,
    'name', o.customer_name, 'email', o.customer_email, 'city', o.ship_city, 'pin', o.ship_pin,
    'subtotal', o.subtotal, 'discount', o.discount, 'shipping', o.shipping, 'cod_fee', o.cod_fee, 'total', o.total,
    'refunded_amount', o.refunded_amount,
    'courier', o.courier, 'tracking_url', o.tracking_url, 'tracking_number', o.tracking_number, 'ship_status', o.ship_status, 'eta', o.eta,
    'delivered_at', o.delivered_at,
    'return_until', case when o.delivered_at is not null and s.return_window_days > 0 then o.delivered_at + make_interval(days => s.return_window_days) end,
    'invoice', (select number from public.invoices i where i.order_id = o.id),
    'events', (select coalesce(jsonb_agg(jsonb_build_object('at', e.at, 'status', e.status, 'location', e.location) order by e.at desc), '[]')
               from public.shipment_events e where e.order_id = o.id and e.return_id is null),
    'lines', (select coalesce(jsonb_agg(jsonb_build_object('sku', sku, 'category', category, 'colour', colour, 'price', price, 'qty', qty) order by id), '[]')
              from public.order_items where order_id = o.id))
  from public.orders o, public.settings s where o.id = p_id and o.access_token = p_token and s.id = 1
$$;

-- ---------------------------------------------------------------- delivery estimate cache (filled by the delivery-estimate function)

create table public.pin_estimates (
  pin         text primary key check (pin ~ '^[1-9][0-9]{5}$'),
  serviceable bool not null,
  days_min    int,
  days_max    int,
  cod         bool not null default false,
  checked_at  timestamptz not null default now()
);
alter table public.pin_estimates enable row level security;

-- ---------------------------------------------------------------- Shiprocket login token (server only)

create table public.integration_tokens (
  name       text primary key,
  token      text not null,
  expires_at timestamptz not null
);
alter table public.integration_tokens enable row level security;
revoke all on public.integration_tokens, public.pin_estimates from anon, authenticated;

-- ---------------------------------------------------------------- who may call what

revoke execute on function public.record_shipment(text, text, text, text, text, text), public.clear_shipment(text, text),
  public.apply_tracking(text, text, timestamptz, text, timestamptz, bool, jsonb), public.issue_invoice(text),
  public.set_return_pickup(bigint, text), public.return_payload(bigint), public.fy_of(timestamptz)
  from public, anon, authenticated;
grant execute on function public.record_shipment(text, text, text, text, text, text), public.clear_shipment(text, text),
  public.apply_tracking(text, text, timestamptz, text, timestamptz, bool, jsonb), public.issue_invoice(text),
  public.set_return_pickup(bigint, text), public.return_payload(bigint), public.fy_of(timestamptz)
  to service_role;
revoke execute on function public.create_invoice(text), public.decide_return(bigint, bool, text),
  public.receive_return(bigint), public.close_return(bigint, bool) from public, anon;
grant execute on function public.create_invoice(text), public.decide_return(bigint, bool, text),
  public.receive_return(bigint), public.close_return(bigint, bool) to authenticated;
-- request_return, order_returns, invoice_lookup and order_lookup stay open: they need the order's secret token
-- (or, for request_return, the signed-in owner of the order).


-- ===== 20261112050000_phase6_compliance.sql
-- VERTU Phase 6: legal disclosures, grievance redressal, privacy requests, listing declarations.
-- Written against: Consumer Protection (E-Commerce) Rules 2020 and the 2026 amendment (notified 9 Sep 2026),
-- Legal Metrology (Packaged Commodities) Rules 2011 rule 6(10), DPDP Act 2023 and DPDP Rules 2025.
-- Not legal advice: have a lawyer review the policies and declarations before launch.

-- ---------------------------------------------------------------- business disclosures

alter table public.settings
  add column registered_address   text not null default '' check (char_length(registered_address) <= 300),
  add column care_email           text check (care_email is null or care_email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  add column care_phone           text check (care_phone is null or care_phone ~ '^\+91[0-9]{10}$'),
  add column care_hours           text not null default 'Monday to Saturday, 10am to 6pm' check (char_length(care_hours) <= 80),
  add column grievance_name       text not null default '' check (char_length(grievance_name) <= 80),
  add column grievance_title      text not null default 'Grievance Officer' check (char_length(grievance_title) <= 80),
  add column grievance_email      text check (grievance_email is null or grievance_email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  add column grievance_phone      text check (grievance_phone is null or grievance_phone ~ '^\+91[0-9]{10}$'),
  add column dispatch_days        int  not null default 2 check (dispatch_days between 0 and 15),
  add column return_shipping_fee  int  not null default 0 check (return_shipping_fee between 0 and 10000),
  add column policies_updated_at  date,
  add column dark_patterns_audit  jsonb not null default '{}'::jsonb; -- { date, by, checks: {pattern: true} }

-- Everything the public pages need (legal name, addresses, contacts, policy numbers). Nothing secret.
create function public.legal_info() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'legal_name', legal_name, 'gstin', gstin, 'registered_address', registered_address,
    'business_address', business_address, 'business_city', business_city, 'business_state', business_state,
    'care_email', care_email, 'care_phone', care_phone, 'care_hours', care_hours,
    'grievance_name', grievance_name, 'grievance_title', grievance_title, 'grievance_email', grievance_email, 'grievance_phone', grievance_phone,
    'return_window_days', return_window_days, 'return_shipping_fee', return_shipping_fee, 'dispatch_days', dispatch_days,
    'shipping_fee', shipping_fee, 'free_shipping_over', free_shipping_over, 'cod_enabled', cod_enabled, 'cod_fee', cod_fee, 'cod_max', cod_max,
    'hold_minutes', hold_minutes, 'policies_updated_at', policies_updated_at,
    'dark_patterns_audit_date', dark_patterns_audit ->> 'date')
  from public.settings where id = 1
$$;

-- ---------------------------------------------------------------- listing declarations (Legal Metrology rule 6(10))

alter table public.categories
  add column declarations jsonb not null default '{}'::jsonb check (jsonb_typeof(declarations) = 'object');
-- { generic_name, net_quantity, country_of_origin, maker (name and address of manufacturer/packer/importer), made_on (month and year) }

update public.categories set declarations = jsonb_build_object('generic_name', unit, 'net_quantity', '1 N (one bag)', 'country_of_origin', 'India', 'maker', '', 'made_on', '')
where declarations = '{}'::jsonb;

-- MRP (inclusive of all taxes). The selling price may not exceed it. Empty means MRP = price.
alter table public.products add column mrp int check (mrp is null or mrp > 0);
alter table public.products add constraint products_price_within_mrp check (mrp is null or price <= mrp);

-- ---------------------------------------------------------------- grievance tickets

create sequence public.ticket_number_seq start 1001;

create table public.support_tickets (
  id              bigint generated always as identity primary key,
  number          text not null unique default ('VRT-T-' || nextval('public.ticket_number_seq')),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  due_at          timestamptz not null default now() + interval '30 days', -- resolve within one month
  name            text not null check (char_length(name) between 1 and 120),
  email           text not null check (email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' and char_length(email) <= 254),
  phone           text not null default '' check (phone = '' or phone ~ '^\+91[0-9]{10}$'),
  order_id        text,
  category        text not null check (category in ('order', 'delivery', 'return', 'payment', 'product', 'cancel', 'privacy', 'other')),
  message         text not null check (char_length(message) between 10 and 4000),
  status          text not null default 'open' check (status in ('open', 'answered', 'closed')),
  user_id         uuid default auth.uid() references auth.users (id) on delete set null,
  last_reply      text,
  last_reply_at   timestamptz,
  resolved_at     timestamptz
);
create index support_tickets_open_idx on public.support_tickets (status, due_at);
create index support_tickets_email_idx on public.support_tickets (lower(email), created_at desc);
create trigger support_tickets_touch before update on public.support_tickets for each row execute function public.touch_updated_at();
alter table public.support_tickets enable row level security;
create policy "tickets admin read" on public.support_tickets for select using (public.is_admin());
create policy "tickets own read" on public.support_tickets for select using (user_id = auth.uid());
revoke insert, update, delete on public.support_tickets from anon, authenticated;

create function public.ticket_payload(p_id bigint) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('number', t.number, 'name', t.name, 'email', t.email, 'phone', t.phone, 'order_id', t.order_id,
    'category', t.category, 'message', t.message, 'created_at', t.created_at, 'due_at', t.due_at, 'reply', t.last_reply, 'status', t.status)
  from public.support_tickets t where t.id = p_id
$$;

-- Anyone can raise a complaint or question. The acknowledgement (with a copy of what they wrote and a
-- ticket number) is emailed straight away, well inside the 48 hours the rules allow.
create function public.open_ticket(p_name text, p_email text, p_phone text, p_order text, p_category text, p_message text)
returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  e text := lower(trim(coalesce(p_email, '')));
  ph text := regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g');
  s public.settings;
  tid bigint;
  num text;
begin
  if e !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' then return jsonb_build_object('ok', false, 'error', 'bad_email'); end if;
  if coalesce(trim(p_name), '') = '' then return jsonb_build_object('ok', false, 'error', 'bad_name'); end if;
  if char_length(trim(coalesce(p_message, ''))) < 10 then return jsonb_build_object('ok', false, 'error', 'too_short'); end if;
  if p_category not in ('order', 'delivery', 'return', 'payment', 'product', 'cancel', 'privacy', 'other') then
    return jsonb_build_object('ok', false, 'error', 'bad_category');
  end if;
  if ph <> '' and ph !~ '^(91)?[6-9][0-9]{9}$' then return jsonb_build_object('ok', false, 'error', 'bad_phone'); end if;
  -- a light brake on abuse: five tickets per email address per day
  if (select count(*) from public.support_tickets where lower(email) = e and created_at > now() - interval '1 day') >= 5 then
    return jsonb_build_object('ok', false, 'error', 'too_many');
  end if;
  insert into public.support_tickets (name, email, phone, order_id, category, message)
  values (left(trim(p_name), 120), e, case when ph = '' then '' else '+91' || right(ph, 10) end,
          nullif(left(upper(trim(coalesce(p_order, ''))), 20), ''), p_category, left(trim(p_message), 4000))
  returning id, number into tid, num;
  select * into s from public.settings where id = 1;
  perform public.enqueue_email('ticket_received', e, public.ticket_payload(tid), 'ticket_received:' || tid);
  perform public.enqueue_email('admin_ticket', coalesce(s.grievance_email, s.notify_email), public.ticket_payload(tid), 'admin_ticket:' || tid);
  return jsonb_build_object('ok', true, 'number', num);
end $$;

create function public.reply_ticket(p_id bigint, p_reply text, p_status text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare t public.support_tickets;
begin
  if not public.is_admin() then raise exception 'not_allowed' using errcode = '42501'; end if;
  if p_status not in ('open', 'answered', 'closed') then return jsonb_build_object('ok', false, 'error', 'bad_status'); end if;
  select * into t from public.support_tickets where id = p_id for update;
  if t.id is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  update public.support_tickets set
    status = p_status,
    last_reply = coalesce(nullif(trim(coalesce(p_reply, '')), ''), last_reply),
    last_reply_at = case when coalesce(trim(p_reply), '') <> '' then now() else last_reply_at end,
    resolved_at = case when p_status = 'closed' then coalesce(resolved_at, now()) else null end
  where id = p_id;
  if coalesce(trim(p_reply), '') <> '' then
    perform public.enqueue_email('ticket_reply', t.email, public.ticket_payload(p_id), 'ticket_reply:' || p_id || ':' || extract(epoch from now())::bigint);
  end if;
  return jsonb_build_object('ok', true);
end $$;

-- ---------------------------------------------------------------- privacy requests (DPDP)

alter table public.data_requests
  add column note text not null default '',
  add column handled_by uuid;

create function public.data_requests_notify() returns trigger
language plpgsql security definer set search_path = '' as $$
declare s public.settings;
begin
  select * into s from public.settings where id = 1;
  perform public.enqueue_email('admin_privacy', coalesce(s.grievance_email, s.notify_email),
    jsonb_build_object('kind', new.kind, 'email', new.email, 'id', new.id), 'admin_privacy:' || new.id);
  perform public.enqueue_email('privacy_received', new.email, jsonb_build_object('kind', new.kind, 'id', new.id), 'privacy_received:' || new.id);
  return new;
end $$;
create trigger data_requests_notify after insert on public.data_requests for each row execute function public.data_requests_notify();

-- Everything held about one person, for an export request (server only; the admin-privacy function calls it).
create function public.personal_data_export(p_user uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'generated_at', now(),
    'account', (select jsonb_build_object('email', u.email, 'created_at', u.created_at, 'last_sign_in_at', u.last_sign_in_at) from auth.users u where u.id = p_user),
    'profile', (select to_jsonb(p) - 'id' from public.profiles p where p.id = p_user),
    'addresses', (select coalesce(jsonb_agg(to_jsonb(a) - 'user_id' - 'id'), '[]') from public.addresses a where a.user_id = p_user),
    'orders', (select coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'placed', o.created_at, 'status', o.status, 'total', o.total,
                 'ship_to', o.ship_address || ', ' || o.ship_city || ' ' || o.ship_pin, 'phone', o.customer_phone,
                 'items', (select jsonb_agg(jsonb_build_object('sku', sku, 'colour', colour, 'qty', qty, 'price', price)) from public.order_items i where i.order_id = o.id))
                 order by o.created_at), '[]')
               from public.orders o where o.customer_id = p_user or lower(o.customer_email) = (select lower(email) from auth.users where id = p_user)),
    'wishlist', (select coalesce(jsonb_agg(sku), '[]') from public.wishlist_items where user_id = p_user),
    'saved_bag', (select items from public.carts where user_id = p_user),
    'newsletter', (select jsonb_build_object('status', n.status, 'since', n.confirmed_at) from public.newsletter_subscribers n where n.email = (select lower(email) from auth.users where id = p_user)),
    'support_tickets', (select coalesce(jsonb_agg(jsonb_build_object('number', t.number, 'created_at', t.created_at, 'message', t.message, 'reply', t.last_reply)), '[]')
               from public.support_tickets t where t.user_id = p_user or lower(t.email) = (select lower(email) from auth.users where id = p_user)),
    'returns', (select coalesce(jsonb_agg(jsonb_build_object('order', r.order_id, 'reason', r.reason, 'status', r.status)), '[]')
               from public.return_requests r join public.orders o on o.id = r.order_id where o.customer_id = p_user));
$$;

-- Erase a person's account data. Orders and invoices stay (tax law requires keeping them) but are detached
-- from the account; the person's newsletter record, tickets' contact details and stock alerts are removed.
-- The auth user itself is deleted by the admin-privacy function (Supabase Auth admin API) right after.
create function public.personal_data_erase(p_user uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare e text;
begin
  select lower(email) into e from auth.users where id = p_user;
  if e is null then return jsonb_build_object('ok', false, 'error', 'unknown_user'); end if;
  delete from public.addresses where user_id = p_user;
  delete from public.wishlist_items where user_id = p_user;
  delete from public.carts where user_id = p_user;
  delete from public.newsletter_subscribers where email = e;
  delete from public.stock_alerts where user_id = p_user or lower(email) = e;
  update public.support_tickets set name = 'Erased', phone = '', message = '[erased at the customer''s request]', user_id = null
    where (user_id = p_user or lower(email) = e) and status = 'closed';
  update public.orders set customer_id = null where customer_id = p_user;
  delete from public.profiles where id = p_user;
  delete from public.admin_users where user_id = p_user;
  return jsonb_build_object('ok', true, 'email', e);
end $$;

create function public.resolve_data_request(p_id bigint, p_note text) returns void
language plpgsql security definer set search_path = '' as $$
declare r public.data_requests;
begin
  if not public.is_owner() then raise exception 'not_allowed' using errcode = '42501'; end if;
  update public.data_requests set resolved_at = now(), note = left(coalesce(p_note, ''), 500), handled_by = auth.uid()
  where id = p_id and resolved_at is null returning * into r;
  if r.id is not null then
    perform public.enqueue_email('privacy_done', r.email, jsonb_build_object('kind', r.kind, 'id', r.id, 'note', r.note), 'privacy_done:' || r.id);
  end if;
end $$;

-- ---------------------------------------------------------------- who may call what

revoke execute on function public.ticket_payload(bigint), public.personal_data_export(uuid), public.personal_data_erase(uuid)
  from public, anon, authenticated;
grant execute on function public.ticket_payload(bigint), public.personal_data_export(uuid), public.personal_data_erase(uuid) to service_role;
revoke execute on function public.reply_ticket(bigint, text, text), public.resolve_data_request(bigint, text) from public, anon;
grant execute on function public.reply_ticket(bigint, text, text), public.resolve_data_request(bigint, text) to authenticated;
-- legal_info and open_ticket stay open to everyone.


-- ===== 20261112060000_phase7_operations.sql
-- Phase 7: rate limits for the public Edge Functions, error monitoring, a health check and alert emails.

-- ---------------------------------------------------------------- rate limits
-- Fixed-window counters keyed by "<function>:<ip>". Only the Edge Functions (service role) use them.
create table public.rate_limits (
  key          text primary key,
  window_start timestamptz not null default now(),
  hits         int not null default 0
);
alter table public.rate_limits enable row level security; -- no policies: invisible to browsers

create function public.hit_rate_limit(p_key text, p_max int, p_window_seconds int)
returns boolean
language plpgsql security definer set search_path = public as $$
declare n int;
begin
  insert into rate_limits as r (key, window_start, hits) values (left(p_key, 200), now(), 1)
  on conflict (key) do update set
    hits = case when r.window_start < now() - make_interval(secs => p_window_seconds) then 1 else r.hits + 1 end,
    window_start = case when r.window_start < now() - make_interval(secs => p_window_seconds) then now() else r.window_start end
  returning hits into n;
  return n <= p_max;
end $$;

-- ---------------------------------------------------------------- monitoring
-- Browser errors, grouped: one row per distinct error, with a count.
create table public.client_errors (
  id          bigint generated always as identity primary key,
  fingerprint text not null unique,
  message     text not null,
  source      text not null default '',
  page        text not null default '',
  stack       text not null default '',
  user_agent  text not null default '',
  release     text not null default '',
  count       int  not null default 1,
  first_seen  timestamptz not null default now(),
  last_seen   timestamptz not null default now(),
  resolved    boolean not null default false
);
create index client_errors_seen_idx on public.client_errors (last_seen desc);
alter table public.client_errors enable row level security;
create policy "client errors admin read" on public.client_errors for select using (public.is_admin());
create policy "client errors admin update" on public.client_errors for update using (public.is_admin()) with check (public.is_admin());

-- Anyone can report a browser error. Text is trimmed, repeats only bump a counter, and at most 300
-- new distinct errors are kept per day, so this can't be used to fill the database.
create function public.log_client_error(p_message text, p_source text default '', p_page text default '',
  p_stack text default '', p_user_agent text default '', p_release text default '')
returns void
language plpgsql security definer set search_path = public as $$
declare
  msg text := left(coalesce(trim(p_message), ''), 500);
  src text := left(coalesce(p_source, ''), 300);
  fp  text;
begin
  if msg = '' then return; end if;
  fp := md5(msg || '|' || regexp_replace(src, ':\d+:\d+$', '') || '|' || coalesce(p_release, ''));
  update client_errors set count = count + 1, last_seen = now(), resolved = false,
    page = left(coalesce(p_page, ''), 300), user_agent = left(coalesce(p_user_agent, ''), 300)
    where fingerprint = fp;
  if found then return; end if;
  if (select count(*) from client_errors where first_seen > now() - interval '1 day') >= 300 then return; end if;
  insert into client_errors (fingerprint, message, source, page, stack, user_agent, release)
  values (fp, msg, src, left(coalesce(p_page, ''), 300), left(coalesce(p_stack, ''), 4000),
          left(coalesce(p_user_agent, ''), 300), left(coalesce(p_release, ''), 40))
  on conflict (fingerprint) do update set count = client_errors.count + 1, last_seen = now();
end $$;

-- Server-side events worth knowing about: Edge Function crashes and rate-limit trips.
create table public.ops_events (
  id      bigint generated always as identity primary key,
  at      timestamptz not null default now(),
  kind    text not null check (kind in ('function_error', 'rate_limited', 'alert')),
  source  text not null,
  message text not null default '',
  detail  jsonb not null default '{}'::jsonb
);
create index ops_events_at_idx on public.ops_events (at desc);
alter table public.ops_events enable row level security;
create policy "ops events admin read" on public.ops_events for select using (public.is_admin());

-- What the admin's System health screen shows.
create function public.system_health()
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  r jsonb;
  cron_failures int := null;
begin
  if not public.is_admin() then raise exception 'not allowed' using errcode = '42501'; end if;
  if to_regclass('cron.job_run_details') is not null then
    execute $q$select count(*)::int from cron.job_run_details where status = 'failed' and start_time > now() - interval '1 day'$q$
      into cron_failures;
  end if;
  select jsonb_build_object(
    'checked_at', now(),
    'emails_failed', (select count(*) from email_outbox where status = 'failed'),
    'emails_waiting', (select count(*) from email_outbox where status = 'pending' and send_after < now() - interval '15 minutes'),
    'emails_sent_day', (select count(*) from email_outbox where status = 'sent' and sent_at > now() - interval '1 day'),
    'last_email_sent', (select max(sent_at) from email_outbox where status = 'sent'),
    'client_errors_day', (select coalesce(sum(count), 0) from client_errors where last_seen > now() - interval '1 day' and not resolved),
    'function_errors_day', (select count(*) from ops_events where kind = 'function_error' and at > now() - interval '1 day'),
    'rate_limited_day', (select count(*) from ops_events where kind = 'rate_limited' and at > now() - interval '1 day'),
    'unpaid_stuck', (select count(*) from orders where payment_status = 'awaiting' and created_at < now() - interval '2 hours'),
    'tickets_overdue', (select count(*) from support_tickets where status <> 'closed' and due_at < now()),
    'privacy_open', (select count(*) from data_requests where resolved_at is null),
    'cron_failures_day', cron_failures,
    'recent_function_errors', coalesce((select jsonb_agg(e) from (select at, source, message from ops_events
                      where kind = 'function_error' order by at desc limit 10) e), '[]'::jsonb)
  ) into r;
  return r;
end $$;

-- For the public uptime check: only "is the database answering, and are emails flowing?".
create function public.health_ping()
returns jsonb
language sql security definer set search_path = public as $$
  select jsonb_build_object(
    'db', true,
    'email_backlog', (select count(*) from email_outbox where status = 'pending' and send_after < now() - interval '15 minutes'),
    'emails_failed', (select count(*) from email_outbox where status = 'failed')
  )
$$;

-- Hourly: email the store about problems, at most once a day per kind of problem.
create function public.ops_check()
returns int
language plpgsql security definer set search_path = public as $$
declare
  s settings;
  issues text[] := '{}';
  n int;
  sent int := 0;
  issue text;
  key text;
begin
  select * into s from settings where id = 1;
  select count(*) into n from email_outbox where status = 'failed' and created_at > now() - interval '1 day';
  if n > 0 then issues := issues || format('emails:%s email%s failed to send in the last day. Open Emails in the admin to retry them.', n, case when n = 1 then '' else 's' end); end if;
  select count(*) into n from email_outbox where status = 'pending' and send_after < now() - interval '30 minutes';
  if n > 0 then issues := issues || format('backlog:%s email%s waiting more than 30 minutes. The email sender may be stopped (check the send-emails job and the RESEND_API_KEY secret).', n, case when n = 1 then ' is' else 's are' end); end if;
  select count(*) into n from ops_events where kind = 'function_error' and at > now() - interval '1 hour';
  if n >= 3 then issues := issues || format('functions:%s server errors in the last hour (checkout, payments, shipping or emails). See System health in the admin.', n); end if;
  select coalesce(sum(count), 0) into n from client_errors where last_seen > now() - interval '1 hour' and not resolved;
  if n >= 25 then issues := issues || format('browser:%s errors in shoppers’ browsers in the last hour. See System health in the admin.', n); end if;
  select count(*) into n from orders where payment_status = 'awaiting' and created_at < now() - interval '2 hours';
  if n > 0 then issues := issues || format('payments:%s online order%s still waiting for payment after 2 hours. Unpaid orders should expire and release their stock within the hour, so the expiry job may be stopped.', n, case when n = 1 then ' is' else 's are' end); end if;

  foreach issue in array issues loop
    key := 'admin_alert:' || split_part(issue, ':', 1) || ':' || to_char(now() at time zone 'Asia/Kolkata', 'YYYY-MM-DD');
    continue when exists (select 1 from email_outbox where dedupe_key = key); -- already alerted today
    perform enqueue_email('admin_alert', s.notify_email,
      jsonb_build_object('kind', split_part(issue, ':', 1), 'message', substr(issue, strpos(issue, ':') + 1)), key);
    insert into ops_events (kind, source, message) values ('alert', split_part(issue, ':', 1), substr(issue, strpos(issue, ':') + 1));
    sent := sent + 1;
  end loop;

  -- housekeeping
  delete from rate_limits where window_start < now() - interval '1 day';
  delete from ops_events where at < now() - interval '90 days';
  delete from client_errors where last_seen < now() - interval '90 days';
  return sent;
end $$;

revoke execute on function public.hit_rate_limit(text, int, int), public.health_ping(), public.ops_check()
  from public, anon, authenticated;
grant execute on function public.hit_rate_limit(text, int, int), public.health_ping(), public.ops_check() to service_role;
revoke execute on function public.system_health() from public, anon;
grant execute on function public.system_health() to authenticated;
revoke execute on function public.log_client_error(text, text, text, text, text, text) from public;
grant execute on function public.log_client_error(text, text, text, text, text, text) to anon, authenticated, service_role;

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('vertu-ops-check', '5 * * * *', 'select public.ops_check()');
  end if;
exception when others then
  raise notice 'ops check job not scheduled: %', sqlerrm;
end $$;


